(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{})["1chr"]={"1":{"1":"Адам, Шет, Энош,","2":"Кенан, Махалалэл, Иеред,","3":"Енох, Метушелах, Ламех,","4":"Ной, Сим, Хам и Яфет.","5":"Сыновья Яфета: Гомер, Магог, Мадай, Яван, Тувал, Мешех и Тирас.","6":"Сыновья Гомера: Ашкеназ, Дифат и Тогарма .","7":"Сыновья Явана: Элиша и Таршиш, а также киттеи и роданеи.","8":"Сыновья Хама: Куш, Мицраим, Пут и Ханаан.","9":"Сыновья Куша: Сава, Хавила, Савта , Раама и Савтеха. Сыновья Раамы: Шева и Дедан.","10":"У Куша также был сын Нимрод – первый богатырь на земле.","11":"От Мицраима произошли: лидийцы, анамеи, лехавеи, нафтухеи,","12":"патрусеи, каслухеи (а от них – филистимляне) и кафтореи.","13":"От Ханаана произошли: Сидон (это его первенец) и Хетт,","14":"а также евусеи, амореи, гиргашеи,","15":"хиввеи, аркеи, синеи,","16":"арвадеи, цемареи и хаматеи.","17":"Сыновья Сима: Элам, Ашшур, Арпахшад, Луд, Арам, Уц, Хул, Гетер и Мешех.","18":"У Арпахшада был сын Шелах, у Шелаха – сын Эвер.","19":"У Эвера родилось двое сыновей: одного звали Пелег, потому что как раз в его время земля была разделена; брата его звали Иоктан.","20":"У Иоктана были сыновья: Алмодад, Шелеф, Хацармавет, Ярах,","21":"Хадорам, Узал, Дикла ,","22":"Гевал, Авимаэл, Сава,","23":"Офир, Хавила и Иовав. Все это сыновья Иоктана.","24":"Сим, Арпахшад, Шелах,","25":"Эвер, Пелег, Рэу ,","26":"Серуг, Нахор, Терах,","27":"Аврам – он же Авраам.","28":"Сыновья Авраама: Исаак и Измаил.","29":"Вот рассказ об их потомках. Первенцем Измаила был Невайот, затем родились Кедар, Адбеэл, Мивсам,","30":"Мишма, Дума, Масса , Хадад, Тема ,","31":"Иетур, Нафиш и Кедма. Это сыновья Измаила.","32":"Вот сыновья, которых родила Кетура, наложница Авраама: Зимран, Иокшан, Медан, Мидьян, Ишбак и Шуах. Сыновьями Иокшана были: Сава и Дедан.","33":"Сыновья Мидьяна: Эфа , Эфер, Енох, Авида и Элдаа. Все они – потомки Кетуры.","34":"Авраам был отцом Исаака. Сыновья Исаака: Исав и Израиль.","35":"Сыновья Исава: Элифаз, Реуэл, Иеуш, Ялам и Корей.","36":"Сыновья Элифаза: Теман, Омар, Цефи, Гатам, Кеназ, Тимна, Амалек.","37":"Сыновья Реуэла: Нахат, Зерах, Шамма и Мизза .","38":"Сыновья Сеира: Лотан, Шовал, Цивеон, Ана, Дишон, Эцер и Дишан.","39":"Сыновья Лотана: Хори и Хомам; сестрой же Лотана была Тимна.","40":"Сыновья Шовала: Альян, Манахат, Гевал, Шефи и Онам. Сыновья Цивеона: Айя и Ана.","41":"Сыновья Аны: Дишон. Сыновья Дишона: Хамран, Эшбан, Итран и Керан.","42":"Сыновья Эцера: Билхан, Зааван, Яакан. Сыновья Дишана: Уц и Аран.","43":"Вот цари, которые правили в Эдоме, еще до того как появились цари у израильтян: Бела, сын Беора, его столица звалась Динхава.","44":"Когда умер Бела, воцарился Иовав, сын Зераха из Боцры .","45":"Когда умер Иовав, воцарился Хушам из страны потомков Темана.","46":"Когда умер Хушам, воцарился Хадад, сын Бедада (тот самый, который разбил мидьянитян на моавских равнинах), его столица звалась Авит.","47":"Когда умер Хадад, воцарился Самла из Масреки .","48":"Когда Самла умер, воцарился Саул из Реховота – Приречного.","49":"Когда Саул умер, воцарился Баал – Ханан, сын Ахбора.","50":"Когда умер Баал – Ханан, воцарился Хадад; столица его звалась Паи; его женой была Мехетавель, дочь Матред, дочери Ме – Захава.","51":"И Хадад умер. Вот кланы Эдома: клан Тимны, клан Алвы, клан Иетета,","52":"клан Оголивамы, клан Элы , клан Пинона,","53":"клан Кеназа, клан Темана, клан Мивцара,","54":"клан Магдиэла и клан Ирама. Таковы кланы Эдома."},"2":{"1":"Вот сыновья Израиля: Рувим, Симеон, Левий, Иуда, Иссахар, Завулон,","2":"Дан, Иосиф, Вениамин, Неффалим, Гад и Асир.","3":"Сыновья Иуды: Эр, Онан и Шела. Эти три сына родились у него от ханаанеянки Бат – Шуи. Эр, первенец Иудин, был неугоден Господу, и Господь умертвил его.","4":"Невестка Иуды Тамар родила от Иуды Пареца и Зераха. Всего сыновей у Иуды было пятеро.","5":"Сыновья Пареца: Хецрон и Хамул.","6":"Сыновья Зераха: Зимри, Этан, Хеман, Калкол и Дара; всего у Зараха было пятеро сыновей.","7":"Сыновья Карми: Ахар (тот, что, нарушив заклятье, навел беду на Израиль).","8":"Сын Этана: Азария.","9":"Сыновья, родившиеся у Хецрона: Иерахмеэл, Рам и Келувай.","10":"Рам был отцом Амминадава; Амминадав – отцом Нахшона (Нахшон был главой потомков Иуды);","11":"сын Нахшона Салма, сын Салмы Боаз;","12":"сын Боаза Овед, сын Оведа Иессей;","13":"у Иессея родился Элиав, его первенец, второй сын Иессея – Авинадав, третий – Шима ,","14":"четвертый – Нетанэл, пятый – Раддай,","15":"шестой – Оцем, седьмой – Давид.","16":"Сестры их: Церуя и Авигаиль. Сыновья Церуи: Авишай, Иоав и Асаил – всего у Церуи было трое сыновей.","17":"У Авигаиль родился сын Амаса; отцом же Амасы был Иетер, измаильтянин.","18":"У Калева, сына Хецрона, от жены его Азувы родилась Иериот. А сыновья ее: Иешер, Шовав и Ардон.","19":"Когда Азува умерла, Калев взял в жены Эфрату, и она родила ему Хура.","20":"У Хура родился Ури, у Ури родился Бецалел.","21":"Затем, уже в шестьдесят лет, Хецрон взял в жены дочь Махира (Махир – отец Галаада), и она родила ему Сегува.","22":"У Сегува родился Яир. У Яира было двадцать три города в Галааде.","23":"Он взял Гешур и Арам, отнял у них Яировы Деревни, Кенат и зависимые от него поселения – всего шестьдесят городов. Все это потомки Махира, отца Галаада.","24":"После смерти Хецрона Калев женился на Эфрате, жене своего отца Хецрона, и она родила ему Ашхура, Ашхур – отец Текоа.","25":"Сыновья Иерахмеэла (первенца Хецрона): первенец – Рам, Буна, Орен, Оцем и Ахия .","26":"Была у Иерахмеэла и другая жена, ее звали Атара; она была матерью Онама.","27":"Сыновья Рама (первенца Иерахмеэла): Маац, Ямин и Экер.","28":"Сыновья Онама: Шаммай и Яда . Сыновья Шаммая: Надав и Авишур.","29":"Жену Авишура звали Авихаиль, она родила ему Ахбана и Молида.","30":"Сыновья Надава: Селед и Аппаим. Селед умер бездетным.","31":"Сын Аппаима: Иши. Сын Иши: Шешан. Сын Шешана: Ахлай.","32":"Сыновья Яды, брата Шаммая: Иетер и Ионафан. Иетер умер бездетным.","33":"Сыновья Ионафана: Пелет и Заза. Все это потомки Иерахмеэла.","34":"У Шешана не было сыновей, а только дочери. Был у Шешана раб, египтянин, по имени Ярха ;","35":"Шешан отдал свою дочь в жены рабу (египтянину по имени Ярха), и она родила ему Аттая;","36":"сын Аттая Нафан, сын Нафана Завад;","37":"сын Завада Эфлал, сын Эфлала Овед;","38":"у Оведа родился сын по имени Иегу, у Иегу родился сын по имени Азария;","39":"у Азарии родился Хелец, у Хелеца родился сын по имени Эласа ;","40":"сын Эласы Сисмай, сын Сисмая Шаллум;","41":"у Шаллума родился сын по имени Иекамия, у Иекамии родился сын по имени Элишама .","42":"Потомки Калева (брата Иерахмеэла): Меша, его первенец, – отец Зифа. Вот потомки Мареши, отца Хеврона.","43":"Сыновья Хеврона: Корей, Таппуах, Рекем и Шема.","44":"У Шемы родился Рахам, отец Иоркеама, а у Рекема родился Шаммай.","45":"Сын Шаммая – Маон, Маон же – отец Бет – Цура.","46":"Наложница Калева Эфа родила Харрана, Моцу и Газеза. У Харрана родился Газез.","47":"Сыновья Яхдая: Регем, Иофам, Гешан, Пелет, Эфа и Шааф.","48":"У наложницы Калева Маахи родились сыновья: Шевер и Тирхана ;","49":"еще она родила Шаафа, отца Мадманны, и Шеву, отца Махбены и Гивы. Дочь Калева звалась Ахса .","50":"Это потомки Калева. Сыновья Хура (Хур – первенец Эфраты): Шовал, отец Кирьят – Иеарима,","51":"Салма, отец Вифлеема, Хареф, отец Бет – Гадера.","52":"Вот потомки Шовала, отца Кирьят – Иеарима: Хароэ , Хаци, Менухот;","53":"роды Кирьят – Иеарима – итритяне, путяне, шуматяне и мишраяне. От них произошли цоратяне и эштауляне.","54":"От Салмы произошли: Вифлеем, нетофатияне, Атрот – бет – Иоав, половина манахтиян – цоряне.","55":"Роды софериян, живущих в Яабеце: тиратияне, шиматияне, сухатияне. Это кинеи, которые происходят от Хаммата, отца Бет – Рехава."},"3":{"1":"Сыновья Давида, родившиеся в Хевроне: первенец Амнон, от Ахиноами изреелитянки; второй сын – Даниил, от Авигаиль из Кармила;","2":"третий – Авессалом, сын Маахи (она была дочерью гешурского царя Талмая); четвертый – Адония, сын Хаггит;","3":"пятый – Шефатия, от Авитали; шестой – Итреам, от жены Давида по имени Эгла .","4":"Всего в Хевроне у Давида родились шесть сыновей; царствовал он там семь лет и шесть месяцев. В Иерусалиме Давид царствовал тридцать три года.","5":"Вот сыновья Давида, которые родились в Иерусалиме: Шима, Шовав, Нафан и Соломон (эти четыре сына от Бат – Шуа, дочери Аммиэла),","6":"Ивхар, Элишама, Элифелет,","7":"Ногах, Нефег, Яфиа,","8":"Элишама, Эльяда и Элифелет (еще девять сыновей).","9":"Вот все сыновья Давида, кроме сыновей от наложниц. Сестрой их была Тамар.","10":"Сын Соломона – Рехавам; сын Рехавама – Авия, сын Авии – Аса, сын Асы – Иосафат,","11":"сын Иосафата – Иорам, сын Иорама – Ахазия, сын Ахазии – Иоас,","12":"сын Иоаса – Амасия, сын Амасии – Азария, сын Азарии – Иофам,","13":"сын Иофама – Ахаз, сын Ахаза – Езекия, сын Езекии – Манассия,","14":"сын Манассии – Амон, сын Амона – Иосия.","15":"Сыновья Иосии: первенец Иоханан, второй сын Иоаким, третий Седекия, четвертый Шаллум.","16":"Сыновья Иоакима: Иехония, Седекия.","17":"Сыновья Иехонии: Ассир, его сын Шеалтиэл,","18":"Малкирам, Педая, Шенаццар, Иекамия, Хошама и Недавия.","19":"Сыновья Педаи: Зоровавель и Шими . Сыновья Зоровавеля: Мешуллам, Ханания (сестрой их была Шеломит).","20":"Еще пятеро: Хашува , Охел, Берехия, Хасадия и Юшав – Хесед.","21":"Сыновья Ханании: Пелатия, Исайя; сын Исайи – Рефая, сын Рефаи – Арнан, сын Арнана – Авдий, сын Авдия – Шехания.","22":"Потомки Шехании: Шемая и сыновья Шемаи – Хаттуш, Игал, Бариах, Неария и Шафат. Всего шестеро.","23":"Сыновья Неарии: Эльйоэнай, Езекия и Азрикам (всего трое сыновей Неарии).","24":"Сыновья Эльйоэная: Ходавия, Эльяшив, Пелая, Аккув, Иоханан, Делая и Анани (всего семеро сыновей Эльйоэная)."},"4":{"1":"Потомки Иуды: Парец, Хецрон, Карми, Хур и Шовал.","2":"У Реаи, сына Шовала, родился Яхат; у Яхата родились Ахумай и Лахад. Это роды цоратян.","3":"Вот сыновья Этама: Изреель, Ишма, Идбаш и сестра их по имени Хацлелпони, а также","4":"Пенуэл, отец Гедора, и Эзер, отец Хуши. Вот потомки Хура, который был первенцем Эфраты и отцом Вифлеема.","5":"У Ашхура, отца Текоа, были две жены: Хела и Наара .","6":"Наара родила ему Ахуззама, Хефера, Темни и Ахаштари. Это сыновья Наары.","7":"Сыновья Хелы: Церет, Цохар и Этнан.","8":"У Коца родились Анув и Цовева; от него же произошли роды Ахархела, сына Харума.","9":"Яабец был самым уважаемым среди своих братьев. Его мать дала ему имя Яабец, говоря: «я родила его в муках».","10":"Яабец воззвал к Богу Израиля: «О, если бы Ты благословил меня, если бы расширил мои владения, если бы Ты поддержал меня и охранил от зла, чтобы не ведал я муки!» И Бог дал Яабецу то, о чем он просил.","11":"У Келува, братом которого был Шуха, родился Мехйр; Мехир – отец Эштона.","12":"У Эштона родились Бет – Рафа, Пасеах и Техинна, отец Ир – Нахаша. Это жители Рехи .","13":"Потомки Кеназа: Отниэл и Серая. Сыновья Отниэла: Хатат.","14":"У Меонотая родился Офра; у Сераи родился Иоав, который был отцом жителей Ге – Харашима (названного так, потому что они были ремесленниками).","15":"Сыновья Калева, сына Иефунне : Иру, Эла и Наам. Сыновья Элы: Кеназ.","16":"Сыновья Иехаллелела: Зиф, Зифа, Тирея и Асарэл.","17":"Сыновья Эзры: Иетер, Меред, Эфер и Ялон. Вот сыновья Битьи, дочери фараона, которую взял в жены Меред: она зачала и родила Мирьяма, Шаммая и Ишбаха, отца Эштемоа.","18":"Жена Мереда, иудеянка, родила Иереда, отца Гедора, Хевера, отца Сохо, и Иекутиэла, отца Заноаха.","19":"Потомками жены Ходии, сестры Нахама, были отцы Кеилы гармитянина и Эштемоа – маахейца.","20":"Сыновья Шимона: Амнон, Ринна, Бенханан и Тилон. Потомки Иши: Зохет и сын Зохета.","21":"Потомки Шелы, сына Иуды: Эр, отец Лехи, Лада, отец Мареши; роды тех, кто выделывал дорогие льняные ткани (клан Ашбеи).","22":"Иоким, жители Козевы, Иоас и Сараф, которые господствовали над моавитянами, жившими в Лехеме (дела давние).","23":"Они были горшечниками, жили в Нетаиме и Гедере, состояли у царя на службе.","24":"Сыновья Симеона: Немуэл, Ямин, Ярив, Зерах и Саул.","25":"Сын Саула – Шаллум; сын Шаллума – Мивсам; сын Мивсама – Мишма.","26":"Сыновья Мишмы: Хаммуэл; сын Хаммуэла – Заккур; сын Заккура – Шими.","27":"У Шими было шестнадцать сыновей и шесть дочерей; а у его братьев сыновей было немного, и весь их род был не столь многочисленен, как род сынов Иуды.","28":"Жили они в Беэр – Шеве, Моладе, Хацар – Шуале,","29":"Билхе , Эцеме, Толаде,","30":"Бетуэле, Хорме, Циклаге,","31":"Бет – Маркавоте, Хацар – Сусиме, Бет – Бири и Шаараиме (это их селения, в которых они жили еще до царствования Давида,","32":"и хутора вокруг них). Этам, Аин, Риммон, Тохен и Ашан (еще пять селений,","33":"а также все хутора, что находятся неподалеку от этих селений, вплоть до Баала). Вот места, где они жили, и их родословие.","34":"Мешовав, Ямлех, Иоша, сын Амасии,","35":"Иоиль, Иегу (отцом Иегу был Иошивия, сын Сераи, сына Асиэла),","36":"Эльйоэнай, Яакова, Иешохая, Асая, Адиэл, Иесимиэл, Беная ,","37":"3иза , сын Шифи, сына Аллона, сына Иедаи, сына Шимри, сына Шемаи –","38":"вот перечислены по именам главы родов. Их роды весьма разрослись.","39":"В поисках пастбищ для скота они доходили до Гедора, до восточной части равнины.","40":"Там они нашли тучные, хорошие пастбища, обширные земли, на которых царил мир и покой. Прежние жители этой страны происходили от Хама.","41":"Те, кто выше был перечислен по именам, пришли туда во времена Иудейского царя Езекии, они уничтожили становища потомков Хама и меунеев, предали их заклятию и истребили. До сих пор они сами живут на их месте, ведь там пастбища для скота.","42":"Пятьсот человек из них (из сыновей Симеона) пошли к Сеирским горам, во главе их стояли сыновья Иши – Пелатия, Неария, Рефая и Уззиэл.","43":"Они перебили последних уцелевших амалекитян и до сих пор живут там сами."},"5":{"1":"Вот потомки Рувима, первенца Израиля. Хотя именно он был первенцем Израиля, но из-за того, что он осквернил ложе своего отца, права первенца перешли к сыновьям Иосифа, сына Израиля.","2":"Хотя Иуда был самым могущественным среди своих братьев и от него произошел правитель, права первенца достались Иосифу.","3":"Вот сыновья Рувима, первенца Израиля: Енох, Паллу, Хецрон и Карми.","4":"Вот потомки Иоиля: сын его Шемая, сын Шемаи – Гог, сын Гога – Шими,","5":"сын Шими – Михей, сын Михея – Реая, сын Реаи – Баал,","6":"сын Баала – Беэра, которого угнал в плен царь Ассирии Тиглатпаласар; Беэра был главой племени Рувима.","7":"Вот их родичи и их семейства, в порядке старшинства по родословной: Иеиэл (их глава), Захария","8":"и Бела, сын Азаза, отцом которого был Шема, потомок Иоиля; Бела жил в Ароэре, а территория их простиралась до Нево и Баал – Меона.","9":"К востоку сыновья Рувима занимали земли до границ пустыни, которая тянется от реки Евфрат, потому что у них было очень много стад в Галааде.","10":"Во времена Саула они вели войну с агарянами, истребили их и стали жить в шатрах по всей восточной стороне Галаада.","11":"Сыновья Гада жили напротив них в Башане (вплоть до Салхи ).","12":"Иоиль (их глава), Шафан (второй человек в племени), Янай и Шафат жили в Башане.","13":"Вот их родичи, люди из их рода: Михаил, Мешуллам, Шева, Иорай, Якан, Зия и Эвер (всего семеро).","14":"Это потомки Авихаила сына Хур, сына Яроаха, сына Гилада, сына Михаила, сына Иешишая, сына Яхдо , сына Буза.","15":"Ах, сын Авдиэла, сына Гун, был главой их рода.","16":"Они жили в Галааде, в Башане, в окрестных селениях и на пастбищах Сарона до самой границы.","17":"Это родословие относится ко временам Иофама, царя Иудейского, и временам Иеровоама, царя Израильского.","18":"Среди потомков Рувима, Гада и половины племени Манассии воинов – людей, готовых к бою, носивших щит и меч, стрелявших из лука и искусных в войне – было сорок четыре тысячи семьсот шестьдесят.","19":"Они воевали с агарянами, Иетуром, Нафишем и Нодавом.","20":"Была им дана помощь против врагов, в их руки были отданы агаряне и все, кто был с агарянами! Воззвали сыны Израиля к Богу во время сражения, и Он услышал мольбы уповающих на Него!","21":"Они захватили скот агарян: пятьдесят тысяч верблюдов, двести пятьдесят тысяч овец, две тысячи ослов; пленных они взяли сто тысяч человек.","22":"Множество убитых полегло! Божьим было то сражение! Потомки Рувима жили на месте агарян вплоть до изгнания.","23":"Потомки половины племени Манассии жили на территории от Башана до Баал – Хермона, Сенира и горы Хермона; были они многочисленны.","24":"Вот главы их родов: Эфер, Иши, Элиэл, Азриэл, Иеремия, Ходавия и Яхдиэл. Все они – могучие воины, именитые мужи, главы своих родов.","25":"Они совершили преступление против Бога своих отцов, стали блудить с богами народов этой страны, тех народов, которых истребил Бог, чтобы дать место сынам Израилевым.","26":"Бог Израиля пробудил воинственный дух в Пуле, царе Ассирии, и в Тиглатпаласаре, царе Ассирии. Выселил он потомков Рувима и Гада и половину племени Манассии, угнал их в Хелах, Хабур, Хару и на реку Гозан, и до сих пор они там."},"6":{"1":"Сыновья Левия: Гершон, Кехат и Мерари .","2":"Сыновья Кехата: Амрам, Ицхар, Хеврон и Уззиэл.","3":"Дети Амрама: Аарон, Моисей и Мирьям. Сыновья Аарона: Надав, Авиуд, Элеазар и Итамар.","4":"Элеазар был отцом Пинехаса, Пинехас был отцом Ави шуа.","5":"Авишуа был отцом Букки, Букки был отцом Уззи.","6":"Уззи был отцом Зерахии, Зерахия был отцом Мерайота.","7":"Мерайот был отцом Амарии, Амария был отцом Ахитува.","8":"Ахитув был отцом Цадока, Цадок был отцом Ахимааца.","9":"Ахимаац был отцом Азарии, Азария был отцом Иоханана.","10":"Иоханан был отцом Азарии, того самого, который был священником в Храме, построенном Соломоном в Иерусалиме.","11":"Азария был отцом Амарии, Амария был отцом Ахитува.","12":"Ахитув был отцом Цадока, Цадок был отцом Шаллума.","13":"Шаллум был отцом Хилкии, Хилкия был отцом Азарии.","14":"Азария был отцом Сераи, Серая был отцом Иоцадака.","15":"Иоцадак был уведен в плен, когда Господь сделал так, что Навуходоносор отправил в изгнание жителей Иудеи и Иерусалима.","16":"Сыновья Левия: Гершом, Кехат и Мерари.","17":"Вот имена сыновей Гершома: Ливни и Шими.","18":"Сыновья Кехата: Амрам, Ицхар, Хеврон и Уззиэл.","19":"Сыновья Мерари: Махли и Муши . Вот роды, которые произошли от Левия, и их родоначальники.","20":"Род Гершома: сын его Ливни; сын Ливни Яхат, сын Яхата Зимма ,","21":"сын Зиммы Иоах, сын Иоаха Иддо, сын Иддо Зерах, сын Зераха Иеатрай.","22":"Потомки Кехата: сын его Амминадав, сын Амминадава Корей, сын Корея Ассир,","23":"сын Ассира Элкана, сын Элканы Эвиасаф, сын Эвиасафа Ассир,","24":"сын Ассира Тахат, сын Тахата Уриэл, сын Уриэла Озия, сын Озии Саул.","25":"Сыновья Элканы: Амасай и Ахимот,","26":"сын Ахимота Элкана, сын Элканы Цофай, сын Цофая Нахат,","27":"сын Нахата Элиав, сын Элиава Иерохам, сын Иерохама Элкана.","28":"Сыновья Самуила: первенец Йоэл, второй сын Авия.","29":"Потомки Мерари: Махли, сын Махли Ливни, сын Ливни Шими, сын Шими Узза ,","30":"сын Уззы Шима, сын Шимы Хаггия, сын Хаггии Асая.","31":"Вот те, кого Давид назначил руководить пением в Храме Господнем, после того как в нем был установлен ковчег.","32":"(До тех пор, пока Соломон не построил Храм Господа в Иерусалиме, они служили певцами пред скинией – Шатром Встречи.) Они исполняли свои служения в соответствии с тем, как было для них установлено.","33":"Вот эти служители и их сыновья. Из потомков Кехата – певец Хеман, сын Иоиля, отцом Иоиля был Самуил,","34":"отцом Самуила – Элкана, отцом Элканы – Иерохам, отцом Ирохама – Элиэл, отцом Элиэла – Тоах,","35":"отцом Тоаха – Цуф, отцом Цуфа – Элкана, отцом Элканы – Махат, отцом Махата – Амасай,","36":"отцом Амасая – Элкана, отцом Элканы – Иоиль, отцом Иоиля – Азария, отцом Азарии – Софония,","37":"отцом Софонии – Тахат, отцом Тахата – Ассир, отцом Ассира – Эвиасаф, отцом Эвиасафа – Корей,","38":"отцом Корея – Ицхар, отцом Ицхара – Кехат, отцом Кехата – Левий, сын Израиля.","39":"Собрат Хемана – Асаф (он стоял справа от Хемана). Отцом Асафа был Берехия, отцом Берехии – Шима,","40":"отцом Шимы – Михаил, отцом Михаила – Баасея, отцом Баасеи – Малкия,","41":"отцом Малкии – Этни, отцом Этни – Зерах, отцом Зераха – Адая ,","42":"отцом Адаи – Этан, отцом Этана – Зимма, отцом Зиммы – Шими,","43":"отцом Шими – Яхат, отцом Яхата – Гершом, сын Левия.","44":"Потомки Мерари – их собратья, стоявшие слева: Этан, сын Киши; отцом Киши был Авди, отцом Авди – Маллух,","45":"отцом Маллуха – Хашавия, отцом Хашавии – Амасия, отцом Амасии – Хилкия,","46":"отцом Хилкии – Амци , отцом Амци – Бани, отцом Бани – Шемер,","47":"отцом Шемера – Махли, отцом Махли – Муши, отцом Муши – Мерари, сын Левия.","48":"Собратья их левиты были назначены исполнять всю работу при скинии Храма Божьего.","49":"Аарон и его сыновья сжигали жертвы на жертвеннике для всесожжении и благовония – на жертвеннике для воскурений; совершали они также всякое священнодействие во Святом Святых и священнодействия для очищения Израиля. Во всем они поступали так, как заповедал раб Божий Моисей.","50":"Вот потомки Аарона: сын его Элеазар, сын Элеазара Пинехас, сын Пинехаса Авишуа,","51":"сын Авишуа Букки, сын Букки Уззи, сын Уззи Зерахия,","52":"сын Зерахии Мерайот, сын Мерайота Амария, сын Амарии Ахитув,","53":"сын Ахитува Цадок, сын Цадока Ахимаац.","54":"Вот где жили левиты: их селения и границы их территории. Потомкам Аарона из рода Кехата по жребию","55":"был отдан Хеврон, расположенный в Иудее, вместе с пастбищами вокруг него, –","56":"однако поля и деревни вокруг города отданы Калеву, сыну Иефунне.","57":"Потомки Аарона получили города – убежища – Хеврон, а также Ливну с пастбищами вокруг него, Яттир и Эштемоа,","58":"Хилез, Девир,","59":"Ашан и Бет – Шемеш с пастбищами вокруг них.","60":"Кроме того, из надела Вениамина им были выделены Гева, Алемет и Анатот с пастбищами вокруг них. Всего городов, распределенных между их родами, – тринадцать.","61":"Остальные левиты из рода Кехата получили по жребию десять селений от племен Ефрема, Дана и от половины племени Манассии.","62":"Левиты из рода Гершома (все их семейства) получили тринадцать селений от племен Иссахара, Асира, Неффалима и от того племени Манассии, что живет в Башане.","63":"Левиты из рода Мерари (все их семейства) получили по жребию двенадцать селений от племен Рувима, Гада и Завулона.","64":"Так израильтяне выделили для левитов селения с пастбищами вокруг них.","65":"Выше были перечислены селения, выделенные левитам по жребию из наделов Иуды, Симеона и Вениамина.","66":"Остальные семейства левитов из рода Кехата получили следующие селения, составившие их территорию. Из надела Ефрема:","67":"города – убежища – Шехем, что в горах Ефрема, с пастбищами вокруг него, а также Гезер,","68":"Иокмеам, Бет – Хорон,","69":"Айялон, Гат – Риммон с пастбищами вокруг них.","70":"Из надела половины племени Манассии: Анер и Билам с пастбищами вокруг них. Вот что получили остальные семейства из рода Кехата.","71":"Левиты из рода Гершома получили следующие селения. От родов половины племени Манассии: Голан, что в Башане, и Аштарот с пастбищами вокруг них.","72":"Из надела Иссахара: Кедеш, Даврат,","73":"Рамот и Анем с пастбищами вокруг них.","74":"Из надела Асира: Машал, Авдон,","75":"Хукок и Рехов с пастбищами вокруг них.","76":"Из надела Неффалима: Кедеш, что в Галилее, Хаммон и Кирьятаим с пастбищами вокруг них.","77":"Остальные левиты – из рода Мерари – получили следующие селения. Из надела Завулона: Риммон и Фавор с пастбищами вокруг них.","78":"Из надела Рувима, на восток от Иордана – Иерихонской реки: Бецер в пустыне, Яхца ,","79":"Кедемот и Мефаат с пастбищами вокруг них.","80":"Из надела Гада: Рамот, что в Галааде, с пастбищами вокруг него, Маханаим,","81":"Хешбон и Язер с пастбищами вокруг них."},"7":{"1":"Сыновья Иссахара: Тола, Пуа, Яшув и Шимрон – всего четверо.","2":"Сыновья Толы: Уззи, Рефая, Иериэл, Яхмай, Ивсам и Самуил – в порядке старшинства перечислены могучие воины, главы родов, произошедших от Толы. Во времена Давида потомков Толы было двадцать две тысячи и шестьсот.","3":"Сыновья Уззи: Израхия. Сыновья Израхии: Михаил, Овадия, Иоиль, Ишшия , – всего пятеро. Все они были главами своих родов.","4":"Под их началом было тридцать шесть тысяч воинов (воины были внесены в списки по родам в порядке старшинства), ведь много у них было жен и сыновей.","5":"Остальных их родичей из родов Иссахара, внесенных в родословные списки, было восемьдесят семь тысяч воинов.","6":"Сыновья Вениамина: Бела, Бехер, Иедиаэл – всего трое.","7":"Сыновья Белы: Эцбон, Уззи, Уззиэл, Иеримот, Ири – всего пятеро; были они главами родов и могучие воины. В родословных списках записано двадцать две тысячи тридцать четыре их потомка.","8":"Сыновья Бехера: Земира, Иоаш, Элиэзер, Эльйоэнай, Омри, Иеремот, Авия, Анатот и Алемет – все это сыновья Бехера.","9":"В родословные списки были внесены двадцать тысяч двести человек (в порядке старшинства и с указанием всех глав родов, могучих воинов).","10":"Сын Иедиаэла: Билхан. Сыновья Билхана: Иеуш, Вениамин, Эхуд, Кенаана, Зетан, Таршиш и Ахишахар.","11":"Все эти потомки Иедиаэла были главами родов, могучими воинами; они возглавляли семнадцать тысяч двести воинов.","12":"Шуппим и Хуппим. Потомки Ира: Хушим, сын Хушима – Ахер.","13":"Сыновья Неффалима: Яхациэл, Гуни, Иецер и Шаллум – все это сыновья Билхи.","14":"Сыновья Манассии: Асриэл, которого родила наложница его, арамеянка; она же родила Махира, отца Галаада.","15":"Махир взял в жены сестру Хуппима и Шуппима; звали ее Мааха. Второго сына Манассии звали Целофхад. У Целофхада были только дочери.","16":"Мааха, жена Махира, родила сына и назвала его Переш, а брата его назвала Шереш. Сыновья Шереша: Улам и Рекем.","17":"Сыновья Улама: Бедан. Вот потомки Галаада, сына Махира, сына Манассии.","18":"Сестра его Молехет родила Ишхода, Авиэзера и Махлу .","19":"Сыновья Шемиды : Ахиан, Шехем, Ликхи и Аниам.","20":"Сыновья Ефрема: Шутелах. Сын Шутелаха – Беред, сын Береда – Тахат, сын Тахата – Элада, сын Элады – Тахат,","21":"сын Тахата – Завад, сыновья Завада – Шутелах, Эзер и Элад. Убили их жители Гата, уроженцы той земли, за то что они пытались захватить их стада.","22":"Долго оплакивал их Ефрем, отец их, а его братья утешали его.","23":"Потом он лег со своей женой, она забеременела и родила сына, и Ефрем дал ему имя Бериа, потому что несчастье случилось в его доме.","24":"Дочерью его была Шеера. Она построила Нижний и Верхний Бет – Хорон и Уззен – Шееру.","25":"Еще сыном Ефрема был Рефах, сын Рефаха – Решеф, сын Ре – шефа – Телах, сын Телаха – Тахан,","26":"сын Тахана – Ладан, сын Ладана – Аммихуд, сын Аммихуда – Элишама,","27":"сын Элишамы – Нон, сын Нона – Иисус.","28":"Вот территории, которыми владели и на которых жили потомки Ефрема: Бет – Эль и селения вокруг него, на востоке – Нааран, на западе – Гезер и селения вокруг него, Шехем и селения вокруг него и земли до Айята с селениями вокруг него.","29":"Во владениях сыновей Манассии были: Бет – Шеан, Таанах, Мегиддо, Дор и селения вокруг них. В этих городах жили потомки Иосифа, сына Израиля.","30":"Сыновья Асира: Имна, Ишва, Ишви, Берна и сестра их Серах.","31":"Сыновья Берии: Хевер и Малкиэл, который был отцом Бирзаита.","32":"У Хевера родились Яфлет, Шомер, Хотам и Шуа, их сестра.","33":"Сыновья Яфлета: Пасах, Бимхал и Ашват. Вот сыновья Яфлета.","34":"Сыновья Шемера: Ахи, Рохга, Хубба и Арам.","35":"Сыновья Хелема, брата его: Цофах, Имна, Шелеш и Амал.","36":"Сыновья Цофаха: Суах, Харнефер, Шуал, Бери, Имра ,","37":"Бецер, Ход, Шамма, Шилша, Итран и Беэра.","38":"Сыновья Иетера: Иефунне, Писпа и Ара .","39":"Сыновья Уллы: Арах, Ханниэл и Риция .","40":"Все это сыновья Асира; они были главами своих родов, отборными воинами, вождями. Войско их по родословным спискам составляло двадцать шесть тысяч человек."},"8":{"1":"Первенец Вениамина – Бела, второй сын – Ашбел, третий – Ахрах,","2":"четвертый – Ноха , а пятый – Рафа .","3":"Сыновья Белы: Адар, Гера, Авиуд,","4":"Авишуа, Нааман, Ахоах,","5":"Гера, Шефуфан и Хурам.","6":"Сыновья Эхуда (они были главами родов жителей Гивы, которые потом были изгнаны в Манахат):","7":"Нааман, Ахия и Гера (он их и изгнал). Гера был отцом Уззы и Ахихуда.","8":"У Шахараима, жившего на Моавских равнинах, после того как он отослал своих жен Хушим и Баару ,","9":"от другой жены по имени Ходеш родились Иовав, Цивья, Меша, Малка ,","10":"Иеуц, Сахия и Мирма. Эти его сыновья стали главами родов.","11":"А от Хушим у него родились Авитув и Элпаал.","12":"Сыновья Элпаала: Эвер, Мишам и Шемед, который построил Оно и Лод с селениями вокруг него.","13":"Берна и Шема были главами родов, живших в Айялоне; однажды они обратили в бегство жителей Гата.","14":"Ахио, Шашак, Иеремот,","15":"3евадия, Арад, Эдер,","16":"Михаил, Ишпа и Иоха были сыновьями Берии.","17":"3евадия, Мешуллам, Хизки, Хевер,","18":"Ишмерай, Излиа и Иовав тоже были сыновьями Элпаала.","19":"Яким, Зихри, Завди ,","20":"Элиэнай, Цнллетай, Элиэл,","21":"Адая, Берая и Шимрат были сыновьями Шими.","22":"Ишпан, Эвер, Элиэл,","23":"Авдон, Зихри, Ханан,","24":"Ханания, Элам, Антотия,","25":"Ифдея и Пенуэл были сыновьями Шашака.","26":"Шамшерай, Шехария, Гофолия,","27":"Яарешия, Илия и Зихри были сыновьями Иерохама.","28":"Это главы родов, перечисленные в порядке старшинства; жили они в Иерусалиме.","29":"В Гаваоне жили отец Гаваона и его жена по имени Мааха.","30":"Их первенцем был Авдон, а потом родились Цур, Киш, Баал, Надав,","31":"Гедор, Ахио, Зехер и Миклот","32":"У Миклота родился Шема. Все они жили в Иерусалиме – там же, где и их сородичи.","33":"У Нера родился Киш, у Киша Саул, у Саула Ионафан, Малкишуа, Авинадав и Эшбаал.","34":"У Ионафана был сын Мерив – Ваал, а у Мерив – Ваала родился Михей.","35":"Сыновьями Михея были Питон, Мелех, Тареа и Ахаз.","36":"У Ахаза родился Иехоада, у Иехоады – Алемет, Азмавет и Зимри, а у Зимри – Моца.","37":"У Моцы родился Бина, сыном которого был Рафа. Сын Рафы – Эласа, а его сын – Ацел.","38":"У Ацела было шестеро сыновей, и звали их так: Азрикам, Бохеру, Измаил, Шеария, Авдий, Ханан – все это сыновья Ацела.","39":"У его брата Эшека первым родился Улам, вторым – Иеуш, а третьим – Элифелет.","40":"Сыновья Улама были могучими воинами – лучниками, у них было очень много детей и внуков – сто пятьдесят. Все они были потомками Вениамина."},"9":{"1":"Так все израильтяне были внесены в родословные списки, они содержатся в Книге царей Израиля. За свои преступления иудеи были угнаны в Вавилон.","2":"Первыми вернулись священники, левиты и храмовые рабы, они поселились в Израиле, каждый в своем владении, в своем селении.","3":"В Иерусалиме тогда поселились люди из племен Иуды, Вениамина, Ефрема и Манассии.","4":"Утай, сын Аммихуда, сына Омри, сына Имри, сына Бани из потомков Пареца, сына Иуды;","5":"из рода Шелы – Асая, его первенец и остальные сыновья;","6":"а из потомков Зераха – Иеуэл и его родичи: шестьсот девяносто человек.","7":"Из племени Вениамина: Саллу , сын Мешуллама, сына Ходавии, сына Хассенуи ;","8":"Ивнея, сын Иерохама; Эла, сын Уззи, сына Михри; Мешуллам, сын Шефатии, сына Реуэла, сына Ивнии .","9":"Родичей их по родословным спискам было девятьсот пятьдесят шесть человек. Все они были главами родов.","10":"Из священников: Иедая, Иехоярив, Яхин,","11":"Азария (управляющий в Божьем Храме), сын Хилкии, сына Мешуллама, сына Цадока, сына Мерайота, сына Ахитува;","12":"Адая, сын Иерохама, сына Пашхура, сына Малкии; Масай, сын Адиэла, сына Яхзеры, сына Мешуллама, сына Мешиллемита, сына Иммера;","13":"а также их родичи, главы отеческих родов – всего тысяча семьсот шестьдесят могучих мужей, служивших в Доме Божьем.","14":"Из левитов: Шемая, сын Хашшува, сына Азрикама, сына Хашавии, одного из сыновей Мерари;","15":"Бакбаккар, Хереш, Галал, Маттания, сын Михея, сына Зихри, сына Асафа;","16":"Авдий, сын Шемаи, сына Галала, сына Иедутуна; Берехия, сын Асы, сына Элканы , который жил в селениях нетофатиян.","17":"Стражи ворот: Шаллум, Аккув, Талмон, Ахиман и их родичи. Главой рода был Шаллум.","18":"И поныне они – стражи стана левитов – охраняют ворота Царские с восточной стороны.","19":"А Шаллум, сын Коре, сына Эвиасафа, сына Корея, и его родичи по отцовской линии несли служение, охраняя порог Шатра, как и отцы их стерегли вход в стан Господень.","20":"Главой их в прежнее время был Пинехас, сын Элеазара; с ним был Господь.","21":"Захария, сын Мешелемии, был стражем у входа в Шатер Собрания.","22":"Всего в стражи ворот было отобрано двести двенадцать человек. Их родословие определено по месту жительства. Давид и провидец Самуил назначили их, доверив им это служение.","23":"Они и их потомки посменно охраняли вход в Дом Господень, то есть в Шатер.","24":"Стражи ворот с четырех сторон – с востока, с запада, с севера и с юга.","25":"Их родичи поочередно приходили из своих селений, чтобы провести с ними по семь дней.","26":"Эта служба была поручена четырем начальникам стражей, левитам, и они наблюдали за комнатами и хранилищами Дома Божьего.","27":"Они ночевали рядом с Домом Божьим, потому что должны были его охранять, а по утрам отпирать.","28":"Некоторые из них ведали богослужебными предметами, выдавая и принимая их по счету;","29":"иные были назначены следить за утварью и за священными сосудами, а также за мукой, вином, маслом, ладаном и благовониями.","30":"Но составлением благовоний занимались те, кто принадлежал к священническому роду,","31":"а одному из левитов – Маттитии, первенцу Шаллума кореита, – было поручено изготовление лепешек.","32":"Некоторые из их родичей – кехатитов заботились о хлебах, которые выкладывались по субботам.","33":"Также были певцы – главы левитских родов. Они находились во внутренних комнатах и были освобождены от работ, потому что их служение длилось день и ночь.","34":"Это главы левитских родов, перечисленные в порядке старшинства; жили они в Иерусалиме.","35":"В Гаваоне жили отец Гаваона Иеиэл и его жена по имени Мааха.","36":"Их первенцем был Авдон, а потом родились Цур, Киш, Баал, Hep, Надав,","37":"Гедор, Ахио, Захария и Миклот.","38":"У Миклота родился Шимам. Все они жили в Иерусалиме – там же, где и их сородичи.","39":"У Нера родился Киш, у Киша – Саул, у Саула – Ионафан, Малкишуа, Авинадав и Эшбаал.","40":"У Ионафана был сын Мерив – Ваал, а у Мерив – Ваала родился Михей.","41":"Сыновьями Михея были Питон, Мелех, Тахреу и Ахаз.","42":"У Ахаза родился Яра, у Яры – Алемет, Азмавет и Зимри, у Зимри – Моца,","43":"у Моцы – Бина и Рефая. Сын Рефаи – Эласа, а его сын – Ацел.","44":"У Ацела было шестеро сыновей, их звали Азрикам, Бохеру, Измаил, Шеария, Авдий и Ханан – все это сыновья Ацела."},"10":{"1":"Сражение филистимлян с израильтянами окончилось победою филистимлян. Израильтяне обратились в бегство, и многие погибли на горе Гилбоа.","2":"Филистимляне погнались за Саулом и его сыновьями и убили Ионафана, Авинадава и Малкишуа, сыновей Саула.","3":"Саул был изнурен сражением. Лучники попали в него своими стрелами и тяжело ранили его.","4":"Тогда он сказал своему оруженосцу: «Обнажи меч и пронзи меня, а иначе придут эти необрезанные и надругаются надо мной». Но оруженосец отказался, сильно испугавшись. Тогда Саул сам бросился на меч.","5":"Видя, что Саул мертв, оруженосец тоже бросился на меч и умер.","6":"Так погиб Саул и трое его сыновей – все его наследники и все слуги его умерли разом.","7":"Когда все израильтяне, жившие в долине, узнали о разгроме и о том, что Саул и его сыновья погибли, они покинули свои города и бежали. Филистимляне пришли и поселились там.","8":"На следующий день, когда филистимляне пришли обирать убитых, они нашли тела Саула и его сыновей, павших на горе Гилбоа.","9":"Сняв с Саула доспехи, отрезав голову и забрав оружие, они провезли это по всей стране филистимлян, неся весть о победе своим идолам и всему народу.","10":"Доспехи они посвятили в Храм своих богов, а череп пригвоздили к стене в храме Дагона.","11":"Когда жители Явеша Галаадского узнали, как филистимляне поступили с Саулом,","12":"то все воины отправились, чтобы забрать тела Саула и его сыновей, и перенесли их в Явеш. Их останки похоронили под тамариском в Явеше. После этого они постились семь дней.","13":"Так погиб Саул. За преступления, которые он совершил против Господа, за то что он не исполнял повелений Господа, за то что обращался за советом к духам,","14":"а Господа не почитал, Господь погубил его и передал царство Давиду, сыну Иессея."},"11":{"1":"Все израильтяне собрались к Давиду в Хеврон и сказали: «Мы – плоть от плоти твоей и кость от кости твоей!","2":"Прежде, когда Саул царствовал над нами, ты возглавлял Израиль в военных походах. Господь сказал тебе: „Ты будешь пасти народ Мой Израиль. Ты будешь его правителем!\"»","3":"Все старейшины Израиля пришли в Хеврон к царю. Там пред Господом царь Давид заключил с ними договор, и они помазали Давида на царство над Израилем. Так сбылось то, что обещал Господь через Самуила.","4":"Давид и все израильтяне отправились в Иерусалим (это и есть Евус), в котором жили евусеи.","5":"Они сказали Давиду: «Ты не войдешь сюда!» Но Давид захватил крепость Сион; это теперь Город Давидов.","6":"Давид сказал: «Кто первым ворвется к евусеям, тот и будет главным, тот станет военачальником!» Первым оказался Иоав, сын Церуи, он стал военачальником.","7":"Давид поселился в захваченной крепости, потому ее и назвали Городом Давидовым.","8":"Давид отстроил город, от Милло и дальше, а Иоав восстановил остальные части города.","9":"Давид укреплялся и возвеличивался, Господь Воинств был с ним.","10":"Вот военачальники Давида, которые поддерживали его во время его правления и вместе со всеми израильтянами помогли ему взойти на царство, как и обещал Господь.","11":"Вот список лучших воинов Давида: Иошовам, сын Хахмони, начальник гвардии. Он за один раз убил копьем триста врагов.","12":"Второй после него человек – Элеазар, сын Додо, ахохитянин. Он был одним из трех воинов,","13":"которые были вместе с Давидом в Пас – Даммиме, где филистимляне собрались для битвы. Там было ячменное поле. И когда народ обратился перед филистимлянами в бегство,","14":"те трое воинов встали посреди поля и, сражаясь с филистимлянами, защитили поле – Господь даровал великую победу.","15":"Эти трое гвардейцев пришли к Давиду в Адулламскую пещеру среди скал; а филистимляне стояли лагерем в долине Рефаимов.","16":"Давид находился в крепости, а отряд филистимлян стоял у Вифлеема.","17":"Давид мучился жаждой и произнес: «Если б кто дал мне напиться воды из колодца, что у ворот Вифлеема!»","18":"Эти трое воинов прорвались через филистимский лагерь и начерпали воды из колодца, что у ворот Вифлеема. Они принесли ее Давиду, но он отказался пить и вылил ее, совершив возлияние Господу.","19":"«Сохрани меня Господь! Не стану я это пить! Это же кровь тех людей, которые рисковали своей жизнью!» – сказал он и не стал пить. Вот чем знамениты эти три воина.","20":"Авишай, брат Иоава, был командиром гвардии. Он убил своим копьем триста врагов, и в гвардии его уважали.","21":"Он был самым прославленным из тридцати и стал во главе них, но в число трех верховных военачальников не входил.","22":"Беная, сын Иехояды, могучий храбрец из Кавцеэла, известен многими делами. Он убил двух могучих, как львы, воинов – моавитян. А однажды, когда выпал снег, он спустился в яму для сбора воды и убил льва, попавшего туда.","23":"Еще он убил огромного египтянина ростом в пять локтей, копье у него в руке было как навой ткацкого станка. А Беная вышел на него с одной палкой, отобрал у него копье и убил египтянина его же собственным копьем.","24":"Вот чем знаменит Беная, сын Иехояды. В гвардии его уважали.","25":"Он был одним из самых знатных гвардейцев, но в число трех верховных военачальников не входил. Давид назначил его ответственным за свою охрану.","26":"Другие могучие воины: Асаил, брат Иоава; Элханан, сын Додо, из Вифлеема;","27":"Шаммот из Харора; Хелец пелонянин;","28":"Ира, сын Иккеша, из Текоа; Авиэзер из Анатота;","29":"Сиббехай из Хуши; Илай ахохитянин;","30":"Махрай из Нетофы; Хелед, сын Бааны, из Нетофы ;","31":"Итай, сын Ривая, из Гивы Вениаминовой; Беная из Пиратона;","32":"Хурай из долины Гааша; Авиэл арватянин;","33":"Азмавет из Бахарума; Эльахба из Шаалвона;","34":"сыновья Хашема гизонитянина; Ионафан, сын Шаге, хараритянин;","35":"Ахиам, сын Сахара, хараритянин; Элифал, сын Ура;","36":"Хефер мехаратянин; Ахия пелонитянин;","37":"Хецро из Кармила; Наарай, сын Эзбая;","38":"Иоиль, брат Нафана; Мивхар, сын Хагри ;","39":"Целек, аммонитянин; Нахрай из Беэрота (он был оруженосцем Иоава, сына Церуи);","40":"Ира итритянин; Гарев итритянин;","41":"Урия хетт; Завад, сын Ахлая;","42":"Адина, сын Шизы, из племени Рувима, предводитель своих соплеменников, и с ним тридцать человек;","43":"Ханан, сын Маахи, Иосафат митнитянин;","44":"Узия аштератянин; Шама и Иеиэл, сыновья Хотама, из Ароэра;","45":"Иедиаэл, сын Шимри, и его брат Иоха тицитянин;","46":"Элиэл махавитянин; Иеривай и Иошавия, сыновья Элнаама; Итма моавитянин;","47":"Элиэл, Овед и Яасиэл из Мецовы ."},"12":{"1":"Вот воины, которые присоединились к Давиду в Циклаге, еще тогда, когда он скрывался от Саула, сына Киша. Это были могучие воины, они помогали Давиду в бою.","2":"Они были вооружены луками и могли метать камни или пускать стрелы и правой, и левой рукой. Они были родичами Саула из племени Вениамина.","3":"Главным был Ахиэзер, он и Иоас – сыновья Шемаи из Гивы; Иезиэл и Пелет, сыновья Азмавета; Бераха и Иегу из Анатота;","4":"Ишмая из Гаваона (гвардеец, начальник гвардии); Иеремия, Яхазиэл, Иоханан, Иозавад из Гедеры;","5":"Элузай, Иеримот, Беалия, Шемария, Шефатия – харупитянин; Элкана, Ишшия, Азарэл, Иоэзер и Иошовам – кореиты;","7":"Иоэла и Зевадия, сыновья Иерохама из Гедора.","8":"Когда Давид был в своем убежище в пустыне, к нему присоединились богатыри из племени Гада, закаленные в боях воины, всегда держащие наготове щит и копье. Они были свирепы, как львы, и быстры, как газели на горах.","9":"Первым был Эзер, вторым Авдий, третьим Элиав,","10":"четвертым Мишманна, пятым Иеремия,","11":"шестым Аттай, седьмым Элиэл,","12":"восьмым Иоханан, девятым Элзавад,","13":"десятым Иеремия, одиннадцатым Махбаннай.","14":"Они были военачальниками из племени Гада; самый слабый из них один мог победить сотню врагов, самый сильный – тысячу.","15":"Это они перешли Иордан в первый месяц, когда река разлилась, затопляя берега, и обратили в бегство жителей речной долины на восточном и на западном берегу.","16":"К Давиду в его убежище пришли также люди из племен Вениамина и Иуды.","17":"Давид встретил их с такими словами: «Если вы пришли ко мне с миром, хотите помочь мне, то я буду вам другом. А если хотите выдать меня врагам, пусть Бог отцов наших увидит это и воздаст вам, ведь я не сделал ничего плохого!»","18":"Тогда дух охватил Амасая, командира гвардии, и он сказал: «Мы твои, Давид! Мы с тобой, сын Иессея! Мир тебе, мир, и мир Богу твоему, который помогает тебе!» Давид принял их и поставил во главе военных отрядов.","19":"И из племени Манассии некоторые люди перешли на сторону Давида, когда он вместе с филистимлянами отправился на бой с Саулом. (Но Давид и его люди не сражались за филистимлян, потому что филистимские правители, посовещавшись, решили отослать его прочь, думая: «Он перебежит на сторону своего господина Саула – это может стоить нам жизни!»)","20":"На пути в Циклаг к Давиду присоединились воины из племени Манассии: Аднах, Иозавад, Иедиаэл, Михаил, Иозавад, Элигу, Циллетай – начальники тысяч из племени Манассии.","21":"Вместе с Давидом они сражались против вражеских отрядов. Все они были могучими воинами и стали военачальниками у Давида.","22":"Изо дня в день люди приходили к Давиду на подмогу, пока не разросся его лагерь, как лагерь Божьего воинства.","23":"Вот список военных отрядов (с указанием числа людей), собравшихся к Давиду в Хеврон, чтобы передать ему царство Саула, как повелел Господь.","24":"От племени Иуды – шесть тысяч восемьсот воинов, способных носить щит и копье.","25":"От племени Симеона – семь тысяч сто могучих воинов.","26":"От племени Левия – четыре тысячи шестьсот;","27":"Иехояда, предводитель потомков Аарона, и с ним три тысячи семьсот;","28":"Цадок, молодой и могучий воин, и весь род его отца – двадцать два военачальника.","29":"От племени Вениамина, родичей Саула, – три тысячи, но большинство из них продолжали служить и царству Саула.","30":"От племени Ефрема – двадцать тысяч восемьсот могучих воинов, прославившихся в своем роду.","31":"От половины племени Манассии – восемнадцать тысяч, которые были назначены поименно, чтобы возвести Давида на царство.","32":"От племени Иссахара – мудрецы, знающие времена, знающие, что нужно делать Израилю; двести предводителей и все их родичи под их началом.","33":"От племени Завулона – пятьдесят тысяч воинов, в полном вооружении, готовых к бою, единодушно желавших поддержать Давида.","34":"От племени Неффалима – тысяча военачальников, которые стояли во главе тридцати семи тысяч воинов, вооруженных щитом и копьем.","35":"От племени Дана – двадцать восемь тысяч шестьсот воинов, готовых к бою.","36":"От племени Асира – сорок тысяч воинов, готовых к бою.","37":"Из-за Иордана, от племен Рувима, Гада и половины племени Манассии – сто двадцать тысяч воинов в полном вооружении.","38":"Все они в боевом порядке пришли в Хеврон с твердым намерением поставить Давида царем над Израилем; этого же единодушно желали и все остальные израильтяне.","39":"Они провели с Давидом три дня в пиршествах, потому что родичи снабдили их необходимым.","40":"И те, кто были неподалеку – вплоть до Иссахара, Завулона и Неффалима – на ослах, верблюдах, мулах и быках привозили им в изобилии еду: муку, инжир, изюм, вино, масло, коров и овец – ибо радость была тогда в Израиле."},"13":{"1":"Давид созвал на совет начальников тысячных отрядов и сотен и всех остальных военачальников,","2":"а затем обратился ко всей общине Израиля: «Если угодно это вам и если есть на то воля Господа, Бога нашего, давайте разошлем гонцов по всему Израилю к нашим родичам и к священникам и левитам, по их городам и пастбищам. Пусть они соберутся к нам,","3":"и тогда перенесем к себе ковчег Бога нашего, к которому мы перестали обращаться во время правления Саула».","4":"Всем понравилось это предложение, все решили так и поступить.","5":"Давид собрал всех израильтян от Шихора Египетского до Аево - Хамата, чтобы перенести ковчег Божий из Кирьят – Иеарима.","6":"Давид и все израильтяне отправились в иудейский город Баалу (в Кирьят – Иеарим), чтобы принести оттуда ковчег Господа Бога, Восседающего на херувимах, ковчег, осененный именем Его.","7":"Ковчег повезли на новой телеге из дома Авинадава, а Узза и Ахио вели телегу.","8":"Давид и все израильтяне что было сил плясали перед Богом, пели, играли на лирах, арфах и трубах, били в бубны и кимвалы.","9":"Когда они подошли к гумну Кидона, волы едва не сбросили с телеги ковчег, и Узза придержал его рукой.","10":"Господь разгневался на Уззу за то, что он дотронулся до ковчега, и убил его; Узза упал замертво там же, перед Богом.","11":"Давид опечалился из-за того, что Господь убил Уззу, и назвал это место Перец – Узза; так оно называется и по сей день.","12":"В этот день Давид испугался Бога и подумал: «Как же я принесу ковчег Господа к себе?!»","13":"Он не стал везти ковчег Господа в Город Давидов и отправил его в дом Овед – Эдома, выходца из Гата.","14":"Три месяца оставался ковчег Господа в доме Овед – Эдома – Господь благословил дом, семью и имущество Овед – Эдома."},"14":{"1":"Хирам, царь Тира, прислал к Давиду своих послов. Они доставили кедровое дерево, и с ними прибыли каменотесы и плотники, чтобы построить Давиду дворец.","2":"И Давид понял, что Господь укрепил его власть над Израилем и возвеличил его царство ради Израиля, Своего народа.","3":"В Иерусалиме Давид взял себе новых жен и у него родились еще сыновья и дочери.","4":"Вот имена тех, кто родился у него в Иерусалиме: Шаммуа, Шовав, Нафан, Соломон,","5":"Ивхар, Элишуа, Элпелет,","6":"Ногах, Нефег, Яфиа,","7":"Элишама, Беэльяда и Элифелет.","8":"Когда филистимляне узнали, что Давид помазан в цари над Израилем, то все они отправились в поход, чтобы разыскать его. Давид, услышав об этом, вышел им навстречу.","9":"Филистимляне, придя, стали разорять долину Рефаимов.","10":"Давид вопросил Бога: «Идти ли мне на филистимлян? Дашь ли Ты мне одолеть их?» Господь ответил ему: «Иди! Я дам тебе одолеть их!»","11":"Израильтяне отправились в Баал – Перацим, и там Давид разгромил филистимлян и сказал: «Господь – как поток, сокрушающий преграды: сокрушил Он врагов моими руками!» Потому это место и называется Баал – Перацим.","12":"Филистимляне побросали там своих богов, которых по приказу Давида сожгли.","13":"И снова филистимляне стали разорять долину.","14":"Давид вновь вопросил Бога и получил от Бога такой ответ: «Не гонись за ними следом, а обойди с тыла и подберись к ним со стороны грушевых деревьев.","15":"Когда услышишь шаги на вершинах груш, бросайся в атаку: это значит, что Господь идет перед тобой, чтобы разгромить филистимское войско».","16":"Давид сделал так, как повелел ему Бог, и разгромил филистимлян от Гаваона до Гезера.","17":"Слава Давида разошлась по всем странам, и все народы стали бояться Господа."},"15":{"1":"Давид построил в Городе Давидовом для себя разные здания, приготовил место для ковчега Божьего и поставил для него шатер.","2":"Давид приказал, чтобы ковчег Божий несли только левиты, потому что навеки их избрал Господь, чтобы они носили ковчег Господень и служили Ему.","3":"Давид собрал всех израильтян в Иерусалиме, чтобы перенести ковчег Господень на место, которое было для него приготовлено.","4":"Вот потомки Аарона и левиты, которых созвал Давид:","5":"из потомков Кехата там был глава их Уриэл и сто двадцать его собратьев;","6":"из потомков Мерари – их глава Асая и двести двадцать его собратьев;","7":"из потомков Гершома – их глава Иоиль и сто тридцать его собратьев;","8":"из потомков Элицафана – их глава Шемая и двести его собратьев;","9":"из потомков Хеврона – их глава Элиэл и восемьдесят его собратьев;","10":"из потомков Уззиэла – их глава Амминадав и сто двадцать его собратьев.","11":"Давид призвал священников Цадока и Авиафара и левитов Уриэла, Асаю, Иоиля, Шемаю, Элиэла и Амминадава","12":"и сказал им: «Вы – главы левитских родов. Так освятите и очистите себя и ваших собратьев и перенесите ковчег Господа, Бога Израилева, на место, которое я приготовил.","13":"За то, что в прошлый раз это делали не вы, за то, что мы не служили Господу как положено, обрушился на нас гнев Господа, Бога нашего».","14":"Священники и левиты освятили и очистили себя, чтобы нести ковчег Господа, Бога Израилева.","15":"Левиты подняли ковчег Божий и положили его шесты себе на плечи, как повелел Господь через Моисея.","16":"Давид приказал начальникам левитов, чтобы они назначили своих собратьев громко и радостно играть на музыкальных инструментах: лирах, арфах, кимвалах.","17":"Левиты назначили Хемана, сына Иоиля, и его собрата Асафа, сына Берехии; из родичей их, потомков Мерари: Этана, сына Кушай;","18":"из дальних их родичей: Захарию, Яазиэла, Шемирамота, Иехиэла, Унни, Элиава, Бенаю, Маасею, Маттитию, Элифелеху, Микнею и стражей ворот Овед – Эдома и Иеиэла.","19":"Музыканты Хеман, Асаф и Этан громко били в медные кимвалы;","20":"Захария, Азиэл, Шемирамот, Иехиэл, Унни, Элиав, Маасея и Беная играли на лирах и исполняли «хааламот»;","21":"а Маттития, Элифелеху, Микнея, Овед – Эдом, Иеиэл и Азазия играли на арфах, исполняя «хашше – минит».","22":"Кенания, главный музыкант левитов, руководил всей игрой на музыкальных инструментах, поскольку был сведущ в этом.","23":"Берехия и Элкана были стражами при ковчеге.","24":"Священники Шевания, Иосафат, Нетанэл, Амасай, Захария, Беная и Элиэзер трубили в трубы перед ковчегом Божьим. Овед – Эдом и Иехия были стражами при ковчеге.","25":"Давид, старейшины Израиля и начальники тысячных отрядов торжественно вынесли ковчег Божьего договора из дома Овед – Эдома.","26":"И помогал Бог левитам, которые несли ковчег Господнего договора, и они принесли Ему в жертву семь быков и семь баранов.","27":"Давид был одет в ризу из тонкого льна; так же были одеты все левиты, несшие ковчег, певцы и Кенания, руководивший игрой на музыкальных инструментах и пением. На Давиде был, кроме ризы, льняной эфод.","28":"Так весь Израиль сопровождал ковчег Господнего договора под ликующие крики, под звуки рога, труб, кимвалов, лир и арф.","29":"Когда ковчег Господнего договора въезжал в Город Давидов, Мелхола, дочь Саула, смотрела в окно. Она увидела, как Давид ликует и пляшет, и ее охватило презрение к царю."},"16":{"1":"Ковчег Божий принесли и установили в шатре, который поставил Давид. Господу принесли жертвы всесожжения и пиршественные жертвы.","2":"Совершив жертвоприношение, Давид благословил народ именем Господа","3":"и раздал всем израильтянам, мужчинам и женщинам, по лепешке хлеба, по лепешке сушеных фиников и по лепешке изюма.","4":"Давид назначил левитов служить перед ковчегом Господним, чтобы они призывали, благодарили и восхваляли Господа, Бога Израиля.","5":"Главным среди них был Асаф, второй после Асафа – Захария; Иеиэл, Шемирамот, Иехиэл, Маттития, Элиав, Беная, Овед – Эдом и Иеиэл играли на лирах и арфах, сам Асаф – на кимвалах.","6":"Священники Беная и Яхазиэл были назначены трубить в трубы перед ковчегом Божьего договора.","7":"В тот день Давид впервые повелел, чтобы Асаф и его собратья воздали хвалу Господу:","8":"Славьте Господа, призывайте имя Его; возвещайте народам о деяниях Его;","9":"пойте о Нем, воспевайте Его; проповедуйте о чудесах Его;","10":"восхваляйте святое имя Его; да веселятся сердца тех, кто к Господу стремится!","11":"Ищите Господа, силу Его, и всегда стремитесь к Нему.","12":"Вспоминайте чудеса, сотворенные Им, знаки и предначертания Его.","13":"Вы, племя Авраамово, – рабы Его, вы, дети Иакова, – избранники Его.","14":"Он – Господь, наш Бог, вся земля подвластна суду Его.","15":"Вечно помните договор с Ним, Он на тысячу поколений заключил его:","16":"заключил договор с Авраамом, клятву дал Исааку,","17":"подтвердил, как закон, Иакову. Договор Его с Израилем – вечен!","18":"Он говорил: «Отдам вам землю Ханаана, всю ее вашим владением сделаю»,","19":"хотя было вас мало там: немногочисленные скитальцы.","20":"Из страны в страну ходили они, среди разных царств и народов.","21":"Но никому не позволил Он обидеть их и царям о них заповедовал:","22":"«Не прикасайтесь к Моим помазанникам, и пророкам Моим зла не делайте».","23":"Пой Господу, вся земля! День за днем возвещайте, как Он нас спас!","24":"Расскажите народам о славе Его, племенам земным – о чудесах Его.","25":"Велик Господь и достоин хвалы, Он страшен и грозен больше всех богов.","26":"Боги других народов – истуканы, а Господь небеса сотворил.","27":"Честь и слава – как свита пред Ним, сила и радость – с Ним рядом.","28":"Величайте Господа, племена людей, величайте Господа, Его славу и мощь!","29":"Величайте славу Господнего имени! Неся дары, идите к Нему. Падите ниц пред Ним во славе Его святой!","30":"Трепещи пред Господом, вся земля; тверда вселенная, не поколеблется.","31":"Да веселятся небеса, да торжествует земля, да возвестят средь народов: «Господь – Царь!»","32":"Грохочет море и все, чем пучина полна; рады степи и все, чем степи полны;","33":"ликуют все деревья в лесу перед Господом, грядущим, чтобы землю судить.","34":"Славьте Господа, ибо Он благ, ибо милость Его вовек.","35":"И еще скажите: «Спаси нас, Бог спасения нашего, собери нас, избавь от чужих народов, дай славить имя Твое святое, дай хвалиться тем, что хвалим Тебя.","36":"Благословен Господь, Бог Израилев, от века и до века!» И весь народ сказал «Аминь», восхваляя Господа.","37":"Давид поручил Асафу и его собратьям, чтобы они всегда совершали служение перед ковчегом Господнего договора, как положено на каждый день;","38":"он также назначил Овед – Эдома и шестьдесят восемь его собратьев (Овед – Эдом, сын Иедитуна, и Хоса были стражами у ворот).","39":"Священнику Цадоку и его собратьям – священникам, которые служили при шатре Господнем в Гаваонском святилище, он велел,","40":"чтобы они регулярно, утром и вечером, приносили Господу всесожжения на жертвеннике для всесожжении, и делали все, что предписано в Законе, который Господь заповедал Израилю.","41":"С ними были Хеман, Иедутун и все, кто были отобраны и поименно назначены восхвалять Господа, произнося: «Навеки милость Его!»","42":"Хеман и Иедутун играли на трубах, кимвалах и других инструментах Господних. Сыновья Иедутуна были стражами ворот.","43":"Весь народ разошелся по домам, и Давид отправился к себе, чтобы благословить свой дом."},"17":{"1":"Давид поселился во дворце. Однажды он сказал пророку Нафану: «Сам я живу в доме из кедра, а ковчег Господнего договора – под навесом из ткани!»","2":"Нафан ответил Давиду: «Делай все, что ты задумал, – Бог будет с тобой».","3":"Но в ту же ночь Нафану было слово от Бога:","4":"«Иди, скажи Моему рабу Давиду: „Так говорит Господь: не ты построишь дом для Меня, чтобы Я в нем поселился.","5":"Ведь с того времени, как Я вывел израильтян из Египта и до сих пор, не было у Меня дома – Я жил в шатрах и скинии.","6":"И где бы ни странствовал Я с израильтянами, обращался ли Я к вождям их, которым поручил пасти народ Мой, с вопросом:, Почему вы не построите Мне дом из кедра?'","7":"Передай Давиду, рабу Моему:, Так говорит Господь Воинств: Я взял тебя с пастбища, где ты пас овец, чтобы поставить тебя наместником над народом Моим Израилем.","8":"Я был с тобой везде, куда бы ты ни ходил, Я уничтожил всех врагов твоих. Я прославлю имя твое, оно станет одним из величайших на земле.","9":"Я назначу место для народа Моего Израиля, укореню его, и он будет жить там без страха; нечестивцы больше не будут притеснять его, как прежде,","10":"в то время, когда Я назначал вождей над народом Моим Израилем. Я дарую тебе победу над всеми врагами твоими. Я возвещаю тебе: Господь возведет тебе дом.","11":"Когда настанет твой срок, и ты отойдешь к предкам, потомка твоего, одного из твоих сыновей, Я поставлю царем после тебя и упрочу царство его.","12":"Он построит Мне дом, а Я укреплю его престол навеки.","13":"Я буду ему Отцом, а он будет Мне сыном, и милости Моей он не лишится, в отличие от твоего предшественника.","14":"Я навеки поставлю его управлять Моим домом и Моим царством, и трон его никогда не поколеблется\"».","15":"Нафан пересказал Давиду все эти слова и видение, которое было ему.","16":"Давид пошел и сел перед Господом и произнес: «Господи Боже! Кто я такой и что такое род мой, что Ты меня так возвеличил?!","17":"Но Ты, Боже, решил дать еще больше. Ты распорядился даже о будущем рода раба Твоего! Господи Боже, Ты заботишься обо мне, будто я великий человек!","18":"Ты так возвеличил раба Твоего, Давида, что нечего ему уже прибавить! Господь, Владыка мой, Ты знаешь раба твоего.","19":"Господи! Ради Твоего раба и по воле Своей Ты устроил и явил все это величие.","20":"Господи, нет равного Тебе! Нет другого Бога, кроме Тебя! Всюду мы слышим подтверждение этому.","21":"И есть ли какой народ на земле, подобный Израилю, народу Твоему, – к которому явился Ты, чтобы сделать его Своим и прославить имя Свое, сотворив дела великие и страшные? Ты прогнал другие народы прочь от Своего народа, который Ты освободил из египетского рабства.","22":"Ты сделал Израиль Своим народом навеки! И Ты, Господь, стал их Богом!","23":"О Господь, пусть сбудется теперь обещание, которое Ты дал рабу Твоему и роду его, – как Ты говорил, так и сделай навеки!","24":"Пусть утвердится и прославится в веках имя Твое словами „Бог Израиля, Бог Израилев – Господь Воинств\", дом раба Твоего Давида да будет всегда перед лицом Твоим.","25":"Ты, Боже мой, сказал рабу Твоему, что построишь ему дом, – и я дерзнул обратиться к Тебе с молитвой.","26":"Господь, Ты – Бог, Ты сообщил рабу Твоему радостную весть.","27":"Так благослови дом раба Твоего, пусть всегда он будет пред лицом Твоим. Ибо если Ты, Господь, благословишь его, навеки он будет благословен»."},"18":{"1":"После этого Давид разбил филистимлян, покорил их и захватил у них Гат с окрестностями.","2":"Давид разбил моавитян. Моавитяне покорились Давиду и стали платить ему дань.","3":"Он разгромил Хададэзера, царя Цова - Хаматы, когда тот выступил в поход на земли у Евфрата.","4":"Давид захватил тогда в плен тысячу колесниц, семь тысяч всадников и двадцать тысяч пеших воинов. Сотню колесниц с конями он оставил себе, остальным коням подрезал сухожилия.","5":"На помощь Хададэзеру, царю Цовы, пришли арамеи из Дамаска, но Давид разгромил и их – двадцать две тысячи арамеев были убиты.","6":"Давид разместил гарнизоны в Араме Дамасском, арамеи подчинились Давиду и стали платить ему дань. Где бы ни воевал Давид, Господь везде даровал ему победу.","7":"Давид захватил золотые колчаны, которые были у слуг Хададэзера, и доставил их в Иерусалим.","8":"В Тевахе и Беротае, городах Хададэзера, царь Давид захватил огромное количество меди, из которой Соломон потом сделал Медное Море, колонны и медные сосуды.","9":"Когда Тоу, царь Хамата, услышал о том, что Давид разгромил войско Хададэзера, царя Цовы,","10":"он отправил своего сына Хадорама к Давиду с посольством, чтобы поздравить царя с победой над Хададэзером, ведь Хададэзер постоянно воевал с Toy. Хадорам принес с собой изделия из серебра, золота и меди.","11":"Царь Давид посвятил их Господу, вместе с серебром и золотом, захваченным у других народов: эдомитян, моавитян, аммонитян, филистимлян, амалекитян.","12":"Авишай, сын Церуи, победил эдомитян в Соляной Долине, там он уничтожил восемнадцать тысяч врагов.","13":"Он поставил в Эдоме наместников, все эдомитяне подчинились Давиду. Где бы Давид ни воевал, Господь везде даровал ему победу.","14":"Давид царствовал над всем Израилем, вершил правосудие и был справедлив ко всему народу.","15":"Иоав, сын Церуи, стоял во главе войска; Иосафат, сын Ахилуда, был секретарем;","16":"Цадок, сын Ахитува, и Авимелех, сын Авиафара, – священниками; Шавша был писцом;","17":"Беная, сын Иехояды, командовал керетянами и пелетянами; сыновья Давида были царскими помощниками."},"19":{"1":"Через некоторое время умер Нахаш, царь аммонитян. После него воцарился его сын.","2":"Давид решил: «Я отплачу добром Хануну, сыну Нахаша; ведь отец его был добр ко мне». Давид отправил послов, чтобы передать Хануну соболезнования по поводу смерти его отца. Когда слуги Давида пришли в землю аммонитян, чтобы передать соболезнования Хануну,","3":"вожди аммонитян сказали Хануну: «Ты и вправду думаешь, что Давид хотел почтить твоего отца и отправил послов, чтобы выразить тебе соболезнования? Нет, Давид прислал к тебе своих людей как разведчиков, чтобы осмотреть нашу страну, а потом уничтожить!»","4":"Ханун схватил слуг Давида, обрил их, отрезал до самого пояса подолы их одеяний, оголив ягодицы, и отпустил.","5":"Когда во время их обратного пути Давиду сообщили, что случилось с этими людьми, он послал встретить их, ведь они были унижены и опозорены. «Оставайтесь в Иерихоне, – приказал им царь, – и когда отрастут ваши бороды, тогда вернетесь».","6":"Аммонитяне, видя, что нажили себе врага в лице Давида, послали тысячу талантов серебра в Арам – Нахараим, Арам – Мааху и Цову, чтобы нанять там колесницы и всадников.","7":"Они наняли тридцать две тысячи колесниц и царя Маахи со всем его войском, которые пришли и стали лагерем перед Медевой. Аммонитяне тем временем проводили набор в собственных городах и сами готовились к войне.","8":"Услышав об этом, Давид послал туда Иоава и все отборное войско.","9":"Аммонитяне выступили и встали боевым порядком у городских ворот, а цари, пришедшие на помощь, встали отдельно в поле.","10":"Иоав, видя, что ему предстоит сражаться на два фронта, отобрал самых лучших израильтян, чтобы выставить их против арамеев,","11":"а все остальное войско поручил своему брату Авишаю и выставил его против аммонитян,","12":"сказав ему так: «Если арамеи будут одолевать меня, ты мне поможешь, а если аммонитяне будут одолевать тебя, то я приду к тебе на помощь.","13":"Мужайся! Мы должны сражаться за наш народ и города Бога нашего, а Господь устроит все так, как Ему угодно».","14":"Иоав со своим войском пошел в наступление на арамеев и обратил их в бегство.","15":"Аммонитяне увидели, что арамеи побежали, и под натиском Авишая, брата Иоава, отступили в город. А Иоав возвратился в Иерусалим.","16":"Видя, что израильтяне разгромили их, арамеи отправили послов, чтобы призвать на помощь арамеев Заречья во главе с Шофахом, полководцем Хададэзера.","17":"Когда Давиду сообщили об этом, он собрал всех израильтян, перешел Иордан, приблизился к врагу и выстроил свое войско. Давид встал боевым порядком против арамеев, и началась битва.","18":"Израильтяне обратили арамеев в бегство. Давид убил семь тысяч колесничих и сорок тысяч пехотинцев и сразил Шофаха, их полководца.","19":"Видя, что израильтяне победили, слуги Хададэзера заключили с Давидом мир и подчинились ему. Больше уже арамеи не пытались помогать аммонитянам."},"20":{"1":"В начале следующего года, во время, когда цари обычно выступают в походы, Иоав во главе военного отряда разорил землю аммонитян, а потом осадил Равву. Давид в это время оставался в Иерусалиме. Иоав ворвался в Равву и уничтожил город.","2":"Давид захватил золотую корону с головы Милхома; она весила талант, и в ней был драгоценный камень. Потом корону возложили на голову Давида. Иоав вынес из города очень богатую добычу.","3":"Жителей его он увел в плен, а сам город разрушил пилами, железными заступами и топорами. И так Давид поступил со всеми аммонитским городами, после чего вместе со всем войском вернулся в Иерусалим.","4":"Потом было еще сражение с филистимлянами в Гезере. Тогда Сиббехай из Хуши убил Сиппая, потомка рефаимов, и филистимляне были покорены.","5":"Было еще сражение с филистимлянами. Элханан, сын Яира, сразил Лахми, брата Голиафа из Гата, – а древко копья Голиафа было как навой ткацкого станка.","6":"Было еще сражение в Гате. Там был воин огромного роста, а на руках и на ногах у него было по шесть пальцев (всего двадцать четыре). Он тоже был из рода рефаимов.","7":"Он насмехался над Израилем, и Ионафан, сын Шимы, Давидова брата, убил его.","8":"Так все эти воины из рода рефаимов, жившие в Гате, погибли от рук Давида и его людей."},"21":{"1":"Сатана напал на Израиль и стал подстрекать Давида устроить в Израиле перепись.","2":"Давид сказал Иоаву и другим предводителям народа: «Ступайте, пересчитайте всех израильтян от Беэр – Шевы до Дана и предоставьте мне отчет, чтобы я знал, сколько у меня народа».","3":"Иоав ответил: «Пусть Господь увеличит во сто крат численность народа! Все они, господин мой царь, твои верные слуги, так зачем же ты собираешься это делать? Мой господин, это ляжет грехом на Израиль!»","4":"Однако Иоав вынужден был подчиниться приказу царя. Он отправился в путь, обошел весь Израиль и вернулся в Иерусалим.","5":"Иоав предоставил Давиду данные переписи народа: в Израиле было миллион сто тысяч мужчин, носящих меч, и в Иудее – четыреста семьдесят тысяч.","6":"Однако левиты и вениамитяне не были включены в перепись, потому что Иоав понимал, что этот приказ царя – мерзость.","7":"Богу была ненавистна перепись, и Он навел беду на Израиль.","8":"Давид обратился к Богу: «Тяжко согрешил я своим поступком! Отпусти Твоему рабу его вину – ведь я совершил это по большой глупости».","9":"Гаду, провидцу Давида, было слово от Господа:","10":"«Иди и объяви Давиду: так говорит Господь: „Три кары Я тебе уготовил! Выбери из них себе одну. Как ты решишь, так Я и поступлю с тобою!\"»","11":"Гад пришел к Давиду и сказал: «Так говорит Господь: прими одно из наказаний.","12":"Либо три года будет голод, либо три месяца враги будут настигать тебя, и ты будешь убегать от них, либо три дня будет мор в твоей стране – тебя поразит меч Господень, Господень ангел погибели пройдет по всем пределам Израиля. Решай, что мне ответить Тому, Кто послал меня».","13":"Давид ответил Гаду: «Тяжко мне очень! Пусть лучше я попаду в руки Господа, – ведь велика милость Его, – только бы не оказаться мне в руках людей!»","14":"Господь навел мор на Израиль, и погибли семьдесят тысяч человек.","15":"Бог уже послал ангела, чтобы уничтожить Иерусалим, но Господь передумал и остановил бедствие, сказав ангелу – губителю: «Хватит! Опусти занесенную руку». Ангел Господа в этот момент был около гумна Орнана – евусея.","16":"Давид поднял глаза и увидел меж небом и землей ангела Господня с обнаженным мечом в руке, простертым над Иерусалимом. Давид и его старейшины, все одетые в дерюгу, пали ниц,","17":"и Давид воззвал к Богу: «Ведь это же я велел провести перепись! Это я согрешил, я, пастух, совершил преступленье, а это овцы – в чем они виноваты?! Господи, Боже мой, на меня обрушь Свой гнев и на мой род, только народ Свой не трогай!»","18":"И тогда ангел Господа через Гада повелел Давиду пойти и воздвигнуть на гумне Орнана – евусея жертвенник Господу.","19":"И Давид пошел, как повелел ему Гад, говоривший от имени Господа.","20":"Орнан обернулся и тоже увидел ангела. Четверо бывших с ним сыновей спрятались. Когда Орнан обмолачивал пшеницу,","21":"к нему пришел Давид. Увидев Давида, Орнан вышел с гумна ему навстречу и поклонился царю до земли.","22":"Давид сказал Орнану: «Продай мне твое гумно, чтобы я мог воздвигнуть на нем жертвенник Господу, чтобы прекратилась кара, постигшая народ. Продай мне его, я заплачу тебе полную цену серебром».","23":"Орнан ответил Давиду: «Возьми даром, господин мой царь, и делай, что тебе угодно. А еще я отдаю быков для всесожжения, молотильные сани на дрова и пшеницу для хлебного приношения – все это я даю даром».","24":"Но царь Давид ответил Орнану: «Нет, я должен заплатить тебе полностью серебром. Я не стану приносить Господу то, что мне не принадлежит, и не буду совершать всесожжение, которое ничего не стоило мне».","25":"Давид отвесил Орнану в уплату за этот участок земли шестьсот шекелей золота.","26":"Там он построил жертвенник для Господа и принес жертвы всесожжения и пиршественные жертвы. Давид воззвал к Господу, и Тот ответил ему – огонь сошел с неба на жертвенник для всесожжении.","27":"И тогда Господь велел ангелу вложить меч в ножны.","28":"Тогда же Давид, увидев, что Господь ответил ему на гумне Орнана – евусея, совершил там жертвоприношение.","29":"В то время скиния Господня, которую сделал в пустыне Моисей, и жертвенник для всесожжении находились в Гаваонском святилище,","30":"и Давид не мог отправиться туда, чтобы послужить Богу, потому что его охватил ужас перед мечом ангела Господа."},"22":{"1":"Тогда Давид сказал: «Здесь будет Храм Господа Бога, и на этом жертвеннике израильтяне будут совершать всесожжения».","2":"Давид приказал собрать всех переселенцев, которые жили в Израиле, и назначил каменотесов, чтобы они готовили камни для строительства Божьего Храма.","3":"Он запас железа для гвоздей, которые пошли на створки ворот и для крепежей, и столько меди, что сосчитать было невозможно.","4":"И кедровых бревен было без счета – ведь жители Сидона и Тира поставляли Давиду кедры в изобилии.","5":"Давид сказал: «Мой сын Соломон еще молод и неопытен, а Храм, который надлежит построить для Господа, должен быть самым знаменитым и великолепным на всей земле. Я должен все приготовить». И потому в конце своей жизни Давид многое приготовил для Храма.","6":"Он позвал своего сына Соломона и заповедал ему построить Храм для Господа, Бога Израилева.","7":"Так сказал Давид Соломону: «Сын мой! Я хотел сам построить Храм для имени Господа, моего Бога.","8":"Но ко мне было слово Господа: „Ты пролил много крови и вел немало войн. Не ты построишь дом для имени Моего, потому что ты пролил много крови предо Мной.","9":"Но у тебя родится сын, и он будет вести мирную жизнь, и Я буду защищать его от всех врагов, которые его окружают. Его имя будет Соломон, и Я дарую Израилю мир и спокойствие во время его правления.","10":"Он построит Храм для имени Моего, он станет Мне сыном, а Я ему – Отцом. Я навеки утвержу его царский престол в Израиле\".","11":"Так пусть будет Господь с тобой, мой сын! Тебе будет сопутствовать успех, и ты построишь Храм Господу, твоему Богу, как Он и обещал.","12":"Пусть Он дарует тебе мудрость и разумение и поставит тебя править Израилем и блюсти Закон Господа, твоего Бога.","13":"Тебе будет сопутствовать удача, если будешь соблюдать и исполнять установления и предписания, которые дал Господь через Моисея Израилю. Будь твердым и стойким! Не бойся, не страшись!","14":"Несмотря на все трудности я запас для Божьего Храма сто тысяч талантов золота, миллион талантов серебра и столько меди и железа, что и сосчитать невозможно; я заготовил бревна и камни. А тебе придется собрать еще больше!","15":"Есть у тебя и множество работников: каменотесов, каменщиков и плотников – и все они знатоки своего ремесла.","16":"Золота, серебра, меди и железа у тебя без счета. Действуй, и да будет с тобой Господь».","17":"Давид приказал всем предводителям Израиля, чтобы они помогали его сыну Соломону:","18":"«Господь, ваш Бог, с вами! Он даровал вам мирную жизнь повсюду, Он отдал в мои руки всех жителей этой страны, и она покорилась Господу и Его народу.","19":"Так устремитесь всем сердцем и всей душой к Господу, вашему Богу! Постройте святилище Господа, вашего Бога и перенесите ковчег Господнего договора и священную Божью утварь в Храм, который будет построен для имени Господа»."},"23":{"1":"Когда Давид состарился и насытился жизнью, он поставил царем над Израилем своего сына Соломона.","2":"Он собрал всех предводителей Израиля, священников и левитов.","3":"Все левиты старше тридцати лет были занесены в списки с указанием общего числа: всего их было тридцать восемь тысяч мужчин.","4":"Из них двадцать четыре тысячи были назначены ответственными за служение в Храме Господнем; шесть тысяч – старостами и судьями;","5":"четыре тысячи – стражами ворот и еще четыре тысячи должны были восхвалять Господа на инструментах, которые для этого сделал Давид.","6":"Он разделил левитов на отряды. У Левия было три сына: Гершон, Кехат и Мерари.","7":"Сыновья Гершона: Ладан и Шими.","8":"Сыновья Ладана: Иехиэл (его первенец), Зетам и Иоиль – всего трое.","9":"У Шими было трое сыновей: Шеломот, Хазиэл и Харан. Это прародители родов Ладана.","10":"Сыновья Шими: Яхат, Зина, Иеуш, Берна. Это четверо сыновей Шими,","11":"причем Яхат был старшим, Зина – вторым; Иеуш и Берна оставили мало потомков, потому они стали считаться за один род.","12":"Сыновья Кехата: Амрам, Ицхар, Хеврон и Уззиэл – всего четверо.","13":"Сыновья Амрама: Аарон и Моисей. Аарон и его потомки были выбраны и посвящены навечно, они – святыня святынь, только они могут сжигать жертвы перед Господом, служить Ему и благословлять именем Его.","14":"Моисей был человеком Божьим, его потомки числятся среди прочих левитов.","15":"Сыновья Моисея: Гершом и Элиэзер.","16":"Сыновья Гершома: Шевуэл (первенец).","17":"Сыновья Элиэзера: Рехавия (первенец). Больше сыновей у него не было, а у Рехавии было очень много сыновей.","18":"Сыновья Ицхара: Шеломит (первенец).","19":"Сыновья Хеврона: первый – Иерия, второй – Амария, третий – Яхазиэл, четвертый – Иекамам.","20":"Сыновья Уззиэла: Михей – первый, Ишшия – второй.","21":"Сыновья Мерари: Махли и Муши. Сыновья Махли: Элеазар и Киш.","22":"Элеазар умер, не оставив сыновей, но у него были дочери. На них женились их двоюродные братья, сыновья Киша.","23":"Сыновья Муши: Махли, Эдер и Иеремот – всего трое.","24":"Вот список левитов старше двадцати лет с указанием имен и общего числа, их роды и прародители. Все они служили в Храме Господа.","25":"Ведь Давид сказал: «Господь, Бог Израиля, даровал мирную жизнь Своему народу и Сам навсегда поселился в Иерусалиме.","26":"Левиты больше не должны носить скинию и предметы, нужные для служения в ней».","27":"В соответствии с последним распоряжением Давида в списки были включены все левиты в возрасте от двадцати лет и старше.","28":"Левиты должны помогать потомкам Аарона в служении в Храме Господнем: заботиться о дворах и комнатах, совершать очищение всех священных предметов и исполнять всякую работу, необходимую во время служения в Божьем Храме.","29":"Они ответственны за хлеб, возлагаемый перед Господом, муку для хлебных приношений, пресные лепешки, жареные лепешки, замесы теста и за размер и количество приношений.","30":"Каждое утро и вечер они должны благодарить и восхвалять Господа.","31":"Они должны регулярно и в нужном количестве совершать перед Господом всесожжения: по субботам, в новолуния и по праздникам.","32":"Они несут службу у Шатра Встречи, отвечают за священные предметы, прислуживают потомкам Аарона, их собратьям, в Храме Господа."},"24":{"1":"Вот потомки Аарона и их распределение. У Аарона были сыновья Надав, Авиуд, Элеазар и Итамар.","2":"Надав и Авиуд умерли прежде своего отца, и детей у них не было. Поэтому священниками стали Элеазар и Итамар.","3":"Давид, Цадок из рода Элеазара и Ахимелех из рода Итамара разделили потомков Аарона на отряды в соответствии с их обязанностями и служениями.","4":"Потомков Элеазара и их предводителей оказалось больше, чем потомков Итамара; деление их было следующим: у потомков Элеазара шестнадцать предводителей (по числу родов), у потомков Итамара – восемь.","5":"Распределение отрядов совершалось по жребию, потому что все они, и те, кто происходил от Элеазара, и те, кто происходил от Итамара, были начальниками в святилище, начальниками Божьими.","6":"Шемая, сын Нетанэла, писец из левитов, занес их в список в присутствии царя, предводителей, священника Цадока и Ахимелеха, сына Авиафара, а также глав священнических и левитских родов. Выбирался род из потомков Элеазара, и выбирался род из потомков Итамара.","7":"Первый жребий выпал Иехояриву, второй – Иедае,","8":"третий – Хариму, четвертый – Сеориму,","9":"пятый – Малкие, шестой – Миямину,","10":"седьмой – Хаккоцу, восьмой – Авие,","11":"девятый – Иисусу, десятый – Шехании,","12":"одиннадцатый – Эльяшиву, двенадцатый – Якиму,","13":"тринадцатый – Хуппе, четырнадцатый – Иешеваву,","14":"пятнадцатый – Билге, шестнадцатый – Иммеру,","15":"семнадцатый – Хезиру, восемнадцатый – Хаппицецу,","16":"девятнадцатый – Петахии, двадцатый – Иезекиилю,","17":"двадцать первый – Яхину, двадцать второй – Гамулу,","18":"двадцать третий – Делае, двадцать четвертый – Маазии.","19":"Их обязанности и служения при Храме Господа установил их предок Аарон, как повелел Господь, Бог Израиля.","20":"Остальные потомки Левия. Из сыновей Амрама: Шуваэл, из сыновей Шуваэла: Иехдея .","21":"О Рехавии. Сыновья Рехавии: Ишшия, его первенец.","22":"Сын Ицхари: Шеломот; сыновья Шеломота: Яхат.","23":"Сыновья Хеврона: Иерия, его первенец, Амария – второй, Яхазиэл – третий, Иекамам – четвертый.","24":"Сыновья Уззиэла: Михей; сыновья Михея: Шамир.","25":"Брат Михея: Ишшия; сыновья Ишшии: Захария.","26":"Сыновья Мерари: Махли и Муши; сыновья Яазии: Бено .","27":"Потомки Мерари: сыновья Яазии, Бено, Шохам, Заккур и Иври .","28":"У Махли был сын Элеазар, но у того не было сыновей.","29":"О Кише. Сыновья Киша: Иерахмеэл.","30":"Сыновья Муши: Махли, Эдер, Иеримот. Это левиты и их роды.","31":"Они тоже бросали жребий, как и их собратья, потомки Аарона, в присутствии царя Давида, Цадока и Ахимелеха, а также глав священнических и левитских родов, причем старшие роды делали это наравне с младшими."},"25":{"1":"Давид и военачальники выбрали потомков Асафа, Хемана и Иедутуна для особого служения: они должны были пророчествовать и играть на арфах, лирах и кимвалах. Вот их список и их обязанности.","2":"Сыновья Асафа: Заккур, Иосиф, Нетания, и Асарэла. Руководил сыновьями Асафа сам Асаф. Он пророчествовал и подчинялся непосредственно царю.","3":"О Иедутуне. Сыновья Иедутуна: Гедалия, Цери, Исайя, Шими, Хашавия и Маттития – всего шестеро. Они подчинялись своему отцу Иедутуну, который играл на арфе и пророчествовал, воздавая Господу благодарность и хвалу.","4":"О Хемане. Сыновья Хемана: Буккия, Маттания, Уззиэл, Шевуэл, Иеримот, Ханания, Ханани, Элиата, Гиддалти, Ромамти – Эзер, Иошбекаша, Маллоти, Хотир и Махазиот.","5":"Все это сыновья Хемана, царского провидца. Бог обещал возвеличить Хемана – и дал ему четырнадцать сыновей и трех дочерей.","6":"Всеми ими руководил их отец, они пели в Храме Божьем, играли на кимвалах, лирах и арфах и служили в Божьем Храме. Все они подчинялись царю, Асафу, Иедутуну и Хема – ну.","7":"Всего их вместе с собратьями – музыкантов Господних, обученных и искусных, – было двести восемьдесят восемь.","8":"Распределяя обязанности, они бросали жребий; все были наравне: старшие и младшие, знатоки и ученики.","9":"Первым по жребию оказался Иосиф (род Асафа); вторым – Гедалия вместе со своими братьями и сыновьями, всего двенадцать человек;","10":"третьим – Заккур вместе со своими братьями и сыновьями, всего двенадцать человек;","11":"четвертым – Ицри вместе со своими братьями и сыновьями, всего двенадцать человек;","12":"пятым – Нетания вместе со своими братьями и сыновьями, всего двенадцать человек;","13":"шестым – Буккия вместе со своими братьями и сыновьями, всего двенадцать человек;","14":"седьмым – Иесарела вместе со своими братьями и сыновьями, всего двенадцать человек;","15":"восьмым – Исайя вместе со своими братьями и сыновьями, всего двенадцать человек;","16":"девятым – Маттания вместе со своими братьями и сыновьями, всего двенадцать человек;","17":"десятым – Шими вместе со своими братьями и сыновьями, всего двенадцать человек;","18":"одиннадцатым – Азарэл вместе со своими братьями и сыновьями, всего двенадцать человек;","19":"двенадцатым – Хашавия вместе со своими братьями и сыновьями, всего двенадцать человек;","20":"тринадцатым – Шуваэл вместе со своими братьями и сыновьями, всего двенадцать человек;","21":"четырнадцатым – Маттития вместе со своими братьями и сыновьями, всего двенадцать человек;","22":"пятнадцатым – Иеремот вместе со своими братьями и сыновьями, всего двенадцать человек;","23":"шестнадцатым – Ханания вместе со своими братьями и сыновьями, всего двенадцать человек;","24":"семнадцатым – Иошбекаша вместе со своими братьями и сыновьями, всего двенадцать человек;","25":"восемнадцатым – Ханани вместе со своими братьями и сыновьями, всего двенадцать человек;","26":"девятнадцатым – Маллоти вместе со своими братьями и сыновьями, всего двенадцать человек;","27":"двадцатым – Элиата вместе со своими братьями и сыновьями, всего двенадцать человек;","28":"двадцать первым – Хотир вместе со своими братьями и сыновьями, всего двенадцать человек;","29":"двадцать вторым – Гиддалти вместе со своими братьями и сыновьями, всего двенадцать человек;","30":"двадцать третьим – Махазиот вместе со своими братьями и сыновьями, всего двенадцать человек;","31":"двадцать четвертым – Ромамти – Эзер вместе со своими братьями и сыновьями, всего двенадцать человек."},"26":{"1":"Вот стражи ворот и их распределение. Из кореитов: Мешелемия, сын Коре, одного из сыновей Асафа.","2":"Сыновья Мешелемии: первенец – Захария, второй его сын – Иедиаэл, третий – Зевадия, четвертый – Ятниэл,","3":"пятый – Элам, шестой – Иехоханан, седьмой – Эльехоэнай.","4":"Сыновья Овед – Эдома: первенец – Шемая, второй его сын – Иозавад, третий – Иоах, четвертый – Сахар, пятый – Нетанэл,","5":"шестой – Аммиэл, седьмой – Иссахар, восьмой – Пеуллетай. Так благословил его Бог!","6":"У его сына Шемаи тоже родились сыновья, они стали главами своего рода, потому что были знатными людьми.","7":"Сыновья Шемаи: Отни , Рефаэл, Овед, Элзавад; их братьями, знатными людьми были Элиту и Семахия.","8":"Все это потомки Овед – Эдома. Всех их, их сыновей и братьев – людей уважаемых и готовых служить – было шестьдесят два человека.","9":"Сыновей и братьев Мешелемии, людей уважаемых, было восемнадцать.","10":"Сыновья Хосы из рода Мерари: старший сын – Шимри (хотя он и не был первенцем, но отец поставил его во главе братьев),","11":"второй – Хилкия, третий – Тевалия, четвертый – Захария. Всего у Хосы было тринадцать сыновей и братьев.","12":"Таково деление стражей ворот. Их предводители служили в Храме Господа наравне со своими собратьями.","13":"Распределяя, у каких ворот кто будет служить, все – и старшие, и младшие, – бросали жребий.","14":"Шелемия получил по жребию Восточные ворота; Захария, его сын, известный своими разумными советами, получил по жребию Северные ворота;","15":"Овед – Эдому достались Южные ворота, а его сыновьям – Складские;","16":"Шуппиму и Хосе выпали Западные ворота, от которых начинается подъем. Стража располагалась так:","17":"с востока ежедневно было шестеро левитов, с севера – четверо, с юга – четверо, а у каждого склада – по двое.","18":"При западном дворе: четверо на дороге, а двое у самого двора.","19":"Так стражи ворот из кореитов и мераритов делились на отряды.","20":"Собратья левитов служили при сокровищнице Божьего Храма и при священной сокровищнице.","21":"Иехиэли был из потомков Ладана – гершунитов, что от Ладана – одним из глав Ладановых родов.","22":"Сыновья Иехиэли, Зетам и его брат Иоиль, служили при сокровищнице Божьего Храма.","23":"Что до потомков Амрама, Ицхара, Хеврона и Уззиэла,","24":"то Шевуэл, сын Гершома, сына Моисея, распоряжался сокровищницей,","25":"а его родичами со стороны Элиэзера были его сыновья Рехавия, Исайя, Иорам, Зихри и Шеломот.","26":"Этот Шеломот и распоряжался священной со – кровищницей, которая состояла из приношений царя Давида, приношений глав родов, командиров тысяч, сотен и других военачальников,","27":"которые посвящали часть военной добычи на благосостояние Господнего Храма.","28":"Все, что посвятили провидец Самуил, Саул, сын Киша, Авнер, сын Нера и Иоав, сын Церуи, – всем этим распоряжался Шеломот со своими братьями.","29":"К потомкам Ицхара принадлежали Кенания и его сыновья, которые были назначены на другое служение – они были писцами и судьями в Израиле.","30":"От Хеврона происходил Хашавия и все его могучие родичи – тысяча семьсот человек, которые были распорядителями и в служении Господу и в царской работе, надзирая над той частью Израиля, что к западу от Иордана.","31":"Из потомков Хеврона был и Иерия, по происхождению первый среди хевронитов. На сороковом году царствования Давида был проведен розыск среди хевронитов, и в Язере, что в Галааде, были найдены могучие мужи.","32":"Всего там оказалось тысяча семьсот старших в роду, и царь Давид назначил их распорядителями во всем, что касалось Бога и царя, над племенами Рувима, Гада и половиной племени Манассии."},"27":{"1":"Вот перечень израильтян в соответствии с главами родов, командирами тысяч и сотен и писцами, которые вместе с царем распоряжались всеми подобающими им делами, чередуясь посменно. Каждая смена заступала на один месяц в году и насчитывала двадцать четыре тысячи человек.","2":"Первую смену, которая заступала в первый месяц, возглавлял Иошовам, сын Завдиэла, эта смена насчитывала двадцать четыре тысячи человек.","3":"Он происходил из потомков Пареца, в первый месяц он был во главе всех военачальников,","4":"Смену для второго месяца возглавлял Додай, ахохитянин, а Миклот управлял этой сменой в двадцать четыре тысячи человек.","5":"Третьим военачальником на третий месяц был Беная, сын Иехояды, первосвященника, во главе смены в двадцать четыре тысячи человек.","6":"Этот Беная был один из Тридцати и во главе Тридцати, а сменой управлял его сын Аммизавад.","7":"Четвертым, на четвертый месяц, был Асаил, брат Иоава, и его сын Зевадия после него – во главе смены в двадцать четыре тысячи человек.","8":"Пятым, на пятый месяц, был вождь Шамхут, потомок Зераха – во главе смены в двадцать четыре тысячи человек.","9":"Шестым, на шестой месяц, был Ира, сын Иккеша из Текоа – во главе смены в двадцать четыре тысячи человек.","10":"Седьмым, на седьмой месяц, был Хелец, пелонянин из племени Ефрема – во главе смены в двадцать четыре тысячи человек.","11":"Восьмым, на восьмой месяц, был Сиббехай из Хуши, из потомков Зераха – во главе смены в двадцать четыре тысячи человек.","12":"Девятым, на девятый месяц, был Авиэзер из Анатота, из племени Вениамина – во главе смены в двадцать четыре тысячи человек.","13":"Десятым, на десятый месяц, был Махрай из Нетофы, из потомков Зераха – во главе смены в двадцать четыре тысячи человек.","14":"Одиннадцатым, на одиннадцатый месяц, был Беная из Пира – тона, из племени Ефрема – во главе смены в двадцать четыре тысячи человек.","15":"Двенадцатым, на двенадцатый месяц, был Хелдай из Нетофы, потомок Отниэла – во главе смены в двадцать четыре тысячи человек.","16":"Израильские племена возглавляли: племя Рувима – вождь Элиэзер, сын Зихри; племя Симеона – Шефатия, сын Маахи;","17":"племя Левия – Хашавия, сын Кемуэла, а потомков Аарона – Цадок;","18":"племя Иуды – Элиав, брат Давида; племя Иссахара – Омри, сын Михаила;","19":"племя Завулона – Ишмая, сын Авдия; племя Неффалима – Иеримот, сын Азриэла;","20":"племя Ефрема – Осия, сын Азазии; половину племени Манассии – Иоиль, сын Педаи;","21":"другую половину племени Манассии, что в Галааде – Иддо, сын Захарии; племя Вениамина – Яасиэл, сын Авнера;","22":"племя Дана – Азарэл, сын Иерохама. Это были вожди израильских племен.","23":"Давид не пересчитывал тех, кому было менее двадцати лет, потому что Господь обещал, что израильтян будет великое множество, как звезд на небе.","24":"Иоав, сын Церуи, начал перепись, но не завершил ее – Божий гнев постиг Израиль, и конечное число не вошло в летопись царя Давида.","25":"Царскими складами заведовал Азмавет, сын Адиэла, а всеми складами, что были на полях, в городах, поселениях и крепостях – Ионафан, сын Озии.","26":"Полевыми работами, то есть обработкой земли, заведовал Эзри, сын Келува;","27":"виноградниками – Шими из Рамы, а их урожаем и запасами вина – Завди из Шефама;","28":"маслинами и сикоморами, что на равнине – Баал – Ханан из Гедера, а запасами масла – Иоас.","29":"Скотом, что пасся в Сароне, заведовал Шитрай из Сарона, а скотом, что в долинах – Шафат, сын Адлая;","30":"верблюдами – Овил измаильтянин, ослицами – Иехдея из Меронота,","31":"а овцами – Язиз из Хагара. Все они распоряжались имуществом царя Давида.","32":"Ионафан, дядя Давида, был, как человек сведущий, советником и писцом. Иехиэл, сын Хахмони, был с сыновьями царя.","33":"Ахитофел был у царя советником, а Хушай, аркей, – другом.","34":"После Ахитофела шли Иехояда, сын Бенаи, и Эвьятар, а Иоав был у царя полководцем."},"28":{"1":"Давид собрал в Иерусалиме всех предводителей Израиля – тех, кто стоял во главе племен и во главе отрядов и был на службе у царя, кто командовал тысячами и сотнями, кто распоряжался царским имуществом и стадами, своих сыновей, евнухов, богатырей и всех могучих воинов.","2":"Царь Давид встал перед ними и обратился к ним с такой речью: «Слушайте, братья мои, мой народ! Я решил построить дом, чтобы он стал пристанищем для ковчега Господнего договора и подножием для Бога нашего. Но когда собрался я его строить,","3":"Бог сказал мне: „Не ты построишь Храм для Моего имени, потому что ты много воевал и пролил немало крови\".","4":"Господь, Бог Израиля, избрал меня из рода моего отца, чтобы навеки поставить царем над Израилем. Из всех племен на первое место Он избрал Иуду, из племени Иуды – род моего отца, а из сыновей моего отца – меня, и пожелал поставить меня царем над Израилем.","5":"Из всех моих сыновей (а Господь дал мне много сыновей!) он избрал Соломона, чтобы посадить его на престол – править царством Господа, Израилем.","6":"Он сказал: „Твой сын Соломон – вот кто построит Мой дом и Мои дворы, потому что Я избрал его, чтобы он был Мне сыном, а Я ему Отцом.","7":"Я навеки утвержу его престол, если он будет исполнять и соблюдать Мои повеления и предписания, как соблюдает сейчас\".","8":"В присутствии всего Израиля, общины Господа, и перед нашим Богом повелеваю: неукоснительно соблюдайте все повеления Господа, Бога нашего, и тогда вы вовеки будете обладать этой прекрасной землей и передавать ее в наследство своим сыновьям.","9":"Ты, сын мой Соломон, помни о Боге твоего отца и служи Ему всем сердцем и всей душой, ибо Господь испытует сердца и ведает тайные помыслы. Если будешь стремиться к Нему, Он явит тебе Себя, а если оставишь, то и Он навсегда тебя отвергнет.","10":"Смотри же, Господь избрал тебя, чтобы ты построил Ему дом, святилище. Будь твердым и действуй!»","11":"Давид передал своему сыну Соломону планы всех построек, которые были им задуманы: притвора Храма и всех остальных его помещений – сокровищниц, верхних помещений, внутренних комнат и помещения, где будет храниться навершие ковчега; дворов Господнего Храма, кладовых, сокровищниц Божьего Храма и хранилищ для священной утвари.","13":"Он рассказал ему о том, как священники и левиты должны делиться на отряды, и об их обязанностях в Храме Господа. Он оставил ему указания обо всей богослужебной утвари для Господнего Храма:","14":"о предметах из золота и о том, сколько требуется золота на каждый из них; о серебряных предметах и о том, сколько требуется серебра на каждый из них;","15":"о золотых светильниках и золотых лампах, о том, сколько должен весить каждый из них; о серебряных светильниках и лампах, о том, сколько должен весить каждый из них, и как используется;","16":"о том, сколько требуется золота на каждый стол для хлеба, возлагаемого перед Господом; о том, сколько требуется серебра для серебряных столов;","17":"о вилках для мяса, чашах для кропления кровью, кувшинах из чистого золота; о золотых чашах и о том, сколько требуется золота на каждую из них; о серебряных чашах и о том, сколько требуется серебра на каждую из них;","18":"о том, сколько потребуется очищенного золота на жертвенник для воскурений; и о колеснице с золотыми херувимами, которые должны были распростертыми крыльями покрывать ковчег Господнего договора.","19":"«Все эти указания я узнал от Господа и записал», – сказал Давид.","20":"Давид сказал своему сыну Соломону: «Будь твердым и стойким! Не бойся, не страшись: Господь Бог, мой Бог – рядом с тобой. Он не оставит и не покинет тебя, доколе не завершишь все работы по строительству Господнего Храма.","21":"Вот отряды священников и левитов, они будут выполнять все служения в Божьем Храме. Для всякой работы у тебя найдутся сведущие и желающие потрудиться люди, а начальники и весь народ будут тебе помощниками в этом деле»."},"29":{"1":"А всем собравшимся царь Давид сказал: «Мой сын Соломон – его одного избрал Бог! – еще слишком молод и неопытен. А дело это великое, ведь это будет дворец не для человека, а для Господа Бога.","2":"Я приложил все силы к тому, чтобы запасти для Божьего Храма золото, необходимое для золотых изделий, серебро, медь, железо, дерево, камни шохам, оправу для камней, сурьму, разнообразные разноцветные и драгоценные камни и множество алебастра.","3":"Заботясь о Храме Бога моего, я передаю на его строительство еще мое собственное золото и серебро, помимо того, что я уже запас для святого Храма:","4":"три тысячи талантов золота (офирского золота!) и семь тысяч талантов чистого серебра на отделку внутренних помещений.","5":"Это золото и серебро пойдет на различные изделия и на плату мастерам. Кто из вас желает послужить Господу?»","6":"Тогда главы родов и племен Израиля, начальники тысячных отрядов и сотен и распорядители царскими работами, стали приносить добровольные пожертвования","7":"и собрали на сооружение Божьего Храма: золота – пять тысяч талантов и десять тысяч дариков, серебра – десять тысяч талантов, меди – восемнадцать тысяч талантов, железа – сто тысяч талантов.","8":"У кого были при себе драгоценные камни, те отдавали их в сокровищницу Господнего Храма, которой распоряжался Иехиэл из рода Гершона.","9":"Народ обрадовался этим пожертвованиям, потому что они были сделаны от всего сердца. Велика была и радость царя Давида.","10":"Давид в присутствии всей общины благословил Господа: «Благословен Ты, Господь, Бог Израиля, наш Отец – извечно и навеки.","11":"Тебе, Господи, принадлежат величие, мощь, слава, процветание и великолепие, ибо Тебе принадлежит все на небе и на земле, и Твое царство вознесено превыше всего на свете.","12":"Ты даруешь богатство и почет, силу и мощь, Ты управляешь всем, от Тебя зависят величие и прочность любого дела.","13":"Боже наш, мы благодарим Тебя и воспеваем преславное имя Твое.","14":"Но кто я такой, и что такое мой народ, чтобы нам самим совершать такие пожертвования? Ведь все исходит от Тебя, и мы возвращаем лишь то, что от Тебя приняли.","15":"Перед Тобой мы все – странники, что пришли лишь на время, как и наши отцы. Наши дни на земле – что тень, и нет у нас надежды на иное.","16":"Господи, Боже наш! Все эти запасы, которые мы приготовили, чтобы построить Храм для святого Твоего имени, мы получили от Тебя, они принадлежат Тебе.","17":"Я знаю, Боже мой, что Ты испытуешь сердца людей и что чистота их Тебе угодна. От чистого сердца я принес все эти пожертвования и вижу, что народ Твой, который находится здесь, с радостью жертвовал Тебе.","18":"Господи, Бог отцов наших, Авраама, Исаака и Израиля, навеки сохрани в Твоем народе чистоту сердечных помыслов, привлеки к Себе их сердца!","19":"А в сердце моего сына Соломона вложи твердое намерение соблюдать Твои заповеди, правила и установления, чтобы совершить все как должно и построить Храм, для которого я все приготовил».","20":"Затем Давид велел всему собранию благословить Господа Бога, и все бывшие там благословили Господа, Бога их отцов, пали ниц перед Господом и перед царем","21":"и принесли жертвы. На следующий день тоже принесли всесожжения: тысячу быков, тысячу баранов и тысячу овец, а также совершили возлияния и жертвы за весь Израиль.","22":"В тот же день устроили они перед Господом пир и вторично поставили на царство Соломона, сына Давида. Во имя Господа помазали его в правители, а священником при этом был Цадок.","23":"Соломон воссел на Господень престол, став царем после своего отца Давида. Он преуспевал, и весь Израиль был покорен ему.","24":"Все вожди, воины и даже все сыновья царя Давида подчинились царю Соломону.","25":"Господь возвеличил Соломона перед всем Израилем и увенчал его столь царственной славой, какой не было до тех пор ни у одного царя в Израиле.","26":"Давид, сын Иессея, был царем над всем Израилем.","27":"Его царствование продолжалось сорок лет: семь лет он царствовал в Хевроне и тридцать три года – в Иерусалиме.","28":"Он умер в глубокой старости, насытившись жизнью, в богатстве и почете, а престол унаследовал его сын Соломон.","29":"Все деяния царя Давида, как ранние, так и поздние, описаны в изречениях провидца Самуила, и в изречениях пророка Нафана, и в изречениях провидца Гада,","30":"равно как и то, что касается его царства и его могущества, и знаменательных событий, которые происходили при нем в Израиле и прочих странах земли."}};
